def parse_workspace_text_max_bytes(value: str) -> int:
    parsed = int(value)
    if parsed < 0:
        raise ValueError("AGENTSDOCK_WORKSPACE_TEXT_MAX_BYTES must be zero or a positive integer")
    return parsed


