def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")


VALID_JOB_SCHEDULE_KINDS = {"interval", "cron", "rrule"}
VALID_JOB_CONTEXT_MODES = {"chat", "standalone"}
CRON_RANDOM_TOKEN_RE = re.compile(r"(?i)\bR\b")
CRON_HASH_TOKEN_RE = re.compile(r"(?i)\bH\b")
RRULE_FREQUENCIES = {"SECONDLY", "MINUTELY", "HOURLY", "DAILY", "WEEKLY", "MONTHLY", "YEARLY"}
RRULE_WEEKDAYS = {"MO", "TU", "WE", "TH", "FR", "SA", "SU"}
RRULE_ALLOWED_PARTS = {
    "FREQ", "UNTIL", "COUNT", "INTERVAL", "BYSECOND", "BYMINUTE", "BYHOUR", "BYDAY",
    "BYMONTHDAY", "BYYEARDAY", "BYWEEKNO", "BYMONTH", "BYSETPOS", "WKST",
}
RRULE_INTEGER_LIST_RANGES = {
    # Python datetime cannot represent RFC leap-second value 60.
    "BYSECOND": (0, 59, True),
    "BYMINUTE": (0, 59, True),
    "BYHOUR": (0, 23, True),
    "BYMONTHDAY": (-31, 31, False),
    "BYYEARDAY": (-366, 366, False),
    "BYWEEKNO": (-53, 53, False),
    "BYMONTH": (1, 12, True),
    "BYSETPOS": (-366, 366, False),
}
MAX_RRULE_COUNT = 10_000
MAX_RRULE_SCAN = MAX_RRULE_COUNT + 10_000
MAX_JOB_INTERVAL_SECONDS = 10 * 366 * 24 * 60 * 60


def normalize_job_timezone(value: Any) -> str:
    name = str(value or "UTC").strip() or "UTC"
    try:
        zone = ZoneInfo(name)
    except (ZoneInfoNotFoundError, ValueError) as exc:
        raise HTTPException(status_code=400, detail=f"invalid IANA timezone: {name}") from exc
    return str(getattr(zone, "key", name) or name)


def parse_job_timestamp(value: str | None, timezone_name: str = "UTC") -> float | None:
    if value is None:
        return None
    clean = str(value).strip()
    if not clean:
        return None
    try:
        numeric = float(clean)
    except ValueError:
        pass
    else:
        if not math.isfinite(numeric):
            raise HTTPException(status_code=400, detail="job timestamp must be finite")
        try:
            datetime.fromtimestamp(numeric, tz=timezone.utc)
        except (OverflowError, OSError, ValueError) as exc:
            raise HTTPException(status_code=400, detail="job timestamp is outside the supported range") from exc
        return numeric
    normalized = clean[:-1] + "+00:00" if clean.endswith("Z") else clean
    try:
        parsed = datetime.fromisoformat(normalized)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail="invalid job timestamp") from exc
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=ZoneInfo(normalize_job_timezone(timezone_name)))
        if not datetime_exists(parsed):
            raise HTTPException(status_code=400, detail="job timestamp does not exist in the selected timezone")
    return parsed.timestamp()


def job_schedule_kind(job: dict[str, Any]) -> str:
    kind = str(job.get("schedule_kind") or "").strip().lower()
    if kind in VALID_JOB_SCHEDULE_KINDS:
        return kind
    if str(job.get("cron_expression") or "").strip():
        return "cron"
    if str(job.get("rrule") or "").strip():
        return "rrule"
    return "interval"


def job_context_mode(job: dict[str, Any]) -> Literal["chat", "standalone"]:
    mode = str(job.get("context_mode") or "").strip().lower()
    return "standalone" if mode == "standalone" else "chat"


def resolve_job_context_contract(
    parent_session: dict[str, Any],
    context_mode: Any,
    backend: Any,
    *,
    context_mode_explicit: bool,
) -> tuple[Literal["chat", "standalone"], str | None]:
    """Resolve legacy omission and validate a job's provider context."""

    normalized_backend = str(backend or "").strip().lower() or None
    if normalized_backend is not None and normalized_backend not in VALID_BACKENDS:
        raise HTTPException(
            status_code=400,
            detail=f"backend must be one of {sorted(VALID_BACKENDS)}",
        )
    mode: Literal["chat", "standalone"] = (
        "standalone"
        if str(context_mode or "").strip().lower() == "standalone"
        else "chat"
    )
    parent_backend = str(
        parent_session.get("backend") or DEFAULT_BACKEND
    ).strip().lower()
    if parent_backend not in VALID_BACKENDS:
        parent_backend = DEFAULT_BACKEND
    if (
        not context_mode_explicit
        and normalized_backend is not None
        and normalized_backend != parent_backend
    ):
        # Contract-v8 and mobile clients predate context_mode. Their explicit
        # alternate backend meant an independent provider run; preserve that
        # intent instead of turning a formerly accepted request into a 400.
        mode = "standalone"
    if (
        mode == "chat"
        and normalized_backend is not None
        and normalized_backend != parent_backend
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "A job that continues in this chat must use the parent chat "
                f"backend ({parent_backend}); choose standalone context to use "
                f"{normalized_backend}."
            ),
        )
    # None intentionally means "inherit the parent chat backend". Preserve it
    # for older clients and legacy job payloads instead of expanding it into a
    # new required field value.
    return mode, normalized_backend


def normalize_cron_expression(value: Any, job_id: str) -> str:
    expression = " ".join(str(value or "").split())
    if not expression:
        raise HTTPException(status_code=400, detail="cron_expression is required for a cron schedule")
    if CRON_RANDOM_TOKEN_RE.search(expression):
        raise HTTPException(
            status_code=400,
            detail="cron random (R) fields are not supported; use hashed (H) fields for stable schedules",
        )
    hash_id = job_id if CRON_HASH_TOKEN_RE.search(expression) else None
    try:
        valid = croniter.is_valid(
            expression,
            hash_id=hash_id,
            second_at_beginning=True,
            strict=True,
        )
    except CroniterError as exc:
        raise HTTPException(status_code=400, detail=f"invalid cron expression: {exc}") from exc
    if not valid:
        raise HTTPException(status_code=400, detail="invalid cron expression")
    return expression


def validate_rrule_parts(expression: str) -> dict[str, str]:
    parts: dict[str, str] = {}
    for raw_part in expression.split(";"):
        key, separator, raw_value = raw_part.partition("=")
        key = key.strip().upper()
        item = raw_value.strip()
        if not separator or not key or not item:
            raise HTTPException(status_code=400, detail="invalid RFC 5545 RRULE property")
        if key not in RRULE_ALLOWED_PARTS:
            raise HTTPException(status_code=400, detail=f"unsupported RFC 5545 RRULE part: {key}")
        if key in parts:
            raise HTTPException(status_code=400, detail=f"RRULE part may appear only once: {key}")
        parts[key] = item

    frequency = parts.get("FREQ", "").upper()
    if frequency not in RRULE_FREQUENCIES:
        raise HTTPException(status_code=400, detail="RRULE requires a valid FREQ part")
    if "COUNT" in parts and "UNTIL" in parts:
        raise HTTPException(status_code=400, detail="RRULE cannot contain both COUNT and UNTIL")
    for key in ("COUNT", "INTERVAL"):
        if key not in parts:
            continue
        if not re.fullmatch(r"\d+", parts[key]):
            raise HTTPException(status_code=400, detail=f"RRULE {key} must be a positive integer")
        if len(parts[key]) > 10:
            raise HTTPException(status_code=400, detail=f"RRULE {key} is too large")
        number = int(parts[key])
        if number < 1:
            raise HTTPException(status_code=400, detail=f"RRULE {key} must be at least 1")
        if key == "COUNT" and number > MAX_RRULE_COUNT:
            raise HTTPException(status_code=400, detail=f"RRULE COUNT must be at most {MAX_RRULE_COUNT}")

    for key, (minimum, maximum, zero_allowed) in RRULE_INTEGER_LIST_RANGES.items():
        if key not in parts:
            continue
        values = parts[key].split(",")
        if any(not re.fullmatch(r"[+-]?\d+", item) for item in values):
            raise HTTPException(status_code=400, detail=f"RRULE {key} contains an invalid integer")
        if any(len(item.lstrip("+-")) > 3 for item in values):
            raise HTTPException(status_code=400, detail=f"RRULE {key} contains an integer that is too large")
        numbers = [int(item) for item in values]
        if any(number < minimum or number > maximum or (number == 0 and not zero_allowed) for number in numbers):
            raise HTTPException(status_code=400, detail=f"RRULE {key} contains a value outside its RFC 5545 range")

    if "BYDAY" in parts:
        for item in parts["BYDAY"].upper().split(","):
            match = re.fullmatch(r"([+-]?\d{1,2})?(MO|TU|WE|TH|FR|SA|SU)", item)
            if not match:
                raise HTTPException(status_code=400, detail="RRULE BYDAY contains an invalid weekday")
            if match.group(1):
                ordinal = int(match.group(1))
                if ordinal == 0 or abs(ordinal) > 53:
                    raise HTTPException(status_code=400, detail="RRULE BYDAY ordinal must be between 1 and 53")
                if frequency not in {"MONTHLY", "YEARLY"}:
                    raise HTTPException(status_code=400, detail="numeric BYDAY is only valid with MONTHLY or YEARLY")
                if frequency == "MONTHLY" and abs(ordinal) > 5:
                    raise HTTPException(status_code=400, detail="numeric MONTHLY BYDAY must be between 1 and 5")
                if frequency == "YEARLY" and "BYWEEKNO" in parts:
                    raise HTTPException(status_code=400, detail="numeric BYDAY cannot be combined with YEARLY BYWEEKNO")
    if "WKST" in parts and parts["WKST"].upper() not in RRULE_WEEKDAYS:
        raise HTTPException(status_code=400, detail="RRULE WKST must be a weekday")
    if "BYWEEKNO" in parts and frequency != "YEARLY":
        raise HTTPException(status_code=400, detail="RRULE BYWEEKNO is only valid with YEARLY")
    if "BYMONTHDAY" in parts and frequency == "WEEKLY":
        raise HTTPException(status_code=400, detail="RRULE BYMONTHDAY is not valid with WEEKLY")
    if "BYYEARDAY" in parts and frequency in {"DAILY", "WEEKLY", "MONTHLY"}:
        raise HTTPException(status_code=400, detail=f"RRULE BYYEARDAY is not valid with {frequency}")
    if "BYSETPOS" in parts and not any(key.startswith("BY") and key != "BYSETPOS" for key in parts):
        raise HTTPException(status_code=400, detail="RRULE BYSETPOS requires another BY rule part")
    return parts


def normalize_rrule_expression(value: Any, timezone_name: str, schedule_start_at: float) -> str:
    expression = str(value or "").strip()
    if expression.upper().startswith("RRULE:"):
        expression = expression[6:].strip()
    if not expression:
        raise HTTPException(status_code=400, detail="rrule is required for an RRULE schedule")
    if "\n" in expression or "\r" in expression:
        raise HTTPException(
            status_code=400,
            detail="rrule must be one RFC 5545 RRULE property, not an iCalendar document",
        )
    validate_rrule_parts(expression)
    zone = ZoneInfo(normalize_job_timezone(timezone_name))
    anchor = datetime.fromtimestamp(float(schedule_start_at), tz=zone)
    try:
        rrulestr(expression, dtstart=anchor)
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail=f"invalid RFC 5545 RRULE: {exc}") from exc
    return expression


def cron_hash_id(expression: str, job_id: str) -> str | None:
    return job_id if CRON_HASH_TOKEN_RE.search(expression) else None


def cron_clock_field_allows(values: list[Any], actual: int) -> bool:
    if values == ["*"] or "*" in values:
        return True
    return actual in values


def cron_candidate_has_requested_clock(iterator: croniter, candidate: datetime) -> bool:
    """Reject croniter's synthetic spring-gap clock time.

    croniter correctly keeps ordinary jobs at local wall time across DST, but
    for a nonexistent clock time it may return the first valid time after the
    gap. We use normal cron semantics instead: skip that nonexistent slot.
    """
    expanded = iterator.expanded
    if not cron_clock_field_allows(expanded[0], candidate.minute):
        return False
    if not cron_clock_field_allows(expanded[1], candidate.hour):
        return False
    expected_seconds = expanded[5] if len(expanded) >= 6 else [0]
    return cron_clock_field_allows(expected_seconds, candidate.second)


def next_job_occurrence(
    job: dict[str, Any],
    after_timestamp: float,
    *,
    inclusive: bool = False,
) -> float | None:
    """Return the next canonical occurrence without anchoring to completion time."""
    kind = job_schedule_kind(job)
    after = float(after_timestamp)
    anchor_value = job.get("schedule_start_at")
    if anchor_value is None:
        anchor_value = job.get("scheduled_run_at")
    if anchor_value is None:
        anchor_value = job.get("next_run_at")

    if kind == "interval":
        if anchor_value is None:
            return None
        anchor = float(anchor_value)
        interval_value = job.get("interval_seconds")
        if not interval_value:
            if anchor > after or (inclusive and anchor >= after):
                return anchor
            return None
        interval = int(interval_value)
        if interval <= 0:
            return None
        if anchor > after or (inclusive and anchor >= after):
            return anchor
        elapsed = max(0.0, after - anchor)
        steps = int(elapsed // interval)
        candidate = anchor + (steps * interval)
        if candidate < after or (not inclusive and candidate <= after):
            candidate += interval
        return candidate

    timezone_name = normalize_job_timezone(job.get("timezone"))
    zone = ZoneInfo(timezone_name)
    anchor = float(anchor_value if anchor_value is not None else after)

    if kind == "cron":
        expression = normalize_cron_expression(job.get("cron_expression"), str(job.get("id") or "job"))
        after = max(after, anchor)
        base = datetime.fromtimestamp(after, tz=zone)
        hashed = cron_hash_id(expression, str(job.get("id") or "job"))
        if inclusive and base.microsecond == 0 and not hashed:
            try:
                if (
                    base.fold == 0
                    and datetime_exists(base)
                    and croniter.match(expression, base, second_at_beginning=True)
                ):
                    return base.timestamp()
            except CroniterError:
                pass
        try:
            iterator = croniter(
                expression,
                base,
                ret_type=datetime,
                hash_id=hashed,
                second_at_beginning=True,
            )
            for _ in range(10000):
                candidate = iterator.get_next(datetime)
                if candidate.tzinfo is None:
                    candidate = candidate.replace(tzinfo=zone)
                if candidate.fold == 1 or not datetime_exists(candidate):
                    continue
                if not cron_candidate_has_requested_clock(iterator, candidate):
                    continue
                timestamp = candidate.timestamp()
                if timestamp > after or (inclusive and timestamp >= after):
                    return timestamp
            raise HTTPException(status_code=400, detail="cron expression produced too many invalid occurrences")
        except CroniterBadDateError:
            return None
        except CroniterError as exc:
            raise HTTPException(status_code=400, detail=f"invalid cron expression: {exc}") from exc

    expression = normalize_rrule_expression(job.get("rrule"), timezone_name, anchor)
    rule_anchor = datetime.fromtimestamp(anchor, tz=zone)
    try:
        parts = validate_rrule_parts(expression)
        count_limit = int(parts["COUNT"]) if "COUNT" in parts else None
        rule_expression = ";".join(
            part for part in expression.split(";") if not part.strip().upper().startswith("COUNT=")
        ) if count_limit is not None else expression
        rule = rrulestr(rule_expression, dtstart=rule_anchor)
        valid_seen = 0
        if count_limit is not None:
            for iteration, candidate in enumerate(rule):
                if iteration >= MAX_RRULE_SCAN:
                    return None
                if candidate.tzinfo is None:
                    candidate = candidate.replace(tzinfo=zone)
                if candidate.fold == 1 or not datetime_exists(candidate):
                    continue
                valid_seen += 1
                if valid_seen > count_limit:
                    return None
                timestamp = candidate.timestamp()
                if timestamp > after or (inclusive and timestamp >= after):
                    return timestamp
            return None

        cursor = datetime.fromtimestamp(after, tz=zone)
        include_cursor = inclusive
        for _ in range(10_000):
            candidate = rule.after(cursor, inc=include_cursor)
            if candidate is None:
                return None
            include_cursor = False
            if candidate.tzinfo is None:
                candidate = candidate.replace(tzinfo=zone)
            if candidate.fold == 1 or not datetime_exists(candidate):
                cursor = candidate
                continue
            timestamp = candidate.timestamp()
            if timestamp > after or (inclusive and timestamp >= after):
                return timestamp
            cursor = candidate
        raise HTTPException(status_code=400, detail="rrule produced too many invalid occurrences")
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail=f"invalid RFC 5545 RRULE: {exc}") from exc


def safe_name(name: str) -> str:
    cleaned = "".join(c if c.isalnum() or c in ("-", "_", ".", " ") else "_" for c in name)
    return cleaned.strip(" .") or "file"


def session_dir(session_id: str) -> Path:
    return STATE_DIR / "sessions" / session_id


def events_path(session_id: str) -> Path:
    return session_dir(session_id) / "events.jsonl"


def uploads_dir(session_id: str) -> Path:
    return session_dir(session_id) / "uploads"


def manifests_dir(session_id: str) -> Path:
    return session_dir(session_id) / "manifests"


def artifact_publications_dir(session_id: str) -> Path:
    return session_dir(session_id) / "artifact_publications"


def codex_manifest_path(session_id: str) -> Path:
    """Stable per-chat artifact handoff path used by provider turns."""
    return manifests_dir(session_id) / "current.json"


def code_diffs_dir(session_id: str) -> Path:
    return CODE_DIFFS_ROOT / session_id


def existing_cwd(requested: str | None) -> str:
    candidates = [requested, DEFAULT_CWD, str(Path.home()), "/tmp"]
    for candidate in candidates:
        if not candidate:
            continue
        path = Path(str(candidate)).expanduser()
        if path.is_dir():
            return str(path)
    return "/tmp"


def validated_fork_cwd(session: dict[str, Any]) -> str:
    """Require an exact usable parent workspace instead of silently falling back."""
    raw = str(session.get("cwd") or "").strip()
    if not raw:
        raise HTTPException(
            status_code=409,
            detail="the parent chat has no working directory; set one before forking",
        )
    expanded = Path(raw).expanduser()
    if not expanded.is_absolute():
        raise HTTPException(
            status_code=409,
            detail="the parent chat working directory must be an absolute path",
        )
    normalized = Path(os.path.normpath(str(expanded)))
    if not normalized.is_dir():
        raise HTTPException(
            status_code=409,
            detail=f"the parent chat working directory is unavailable: {normalized}",
        )
    return str(normalized)


def workspace_http_error(status_code: int, code: str, message: str, action: str | None = None) -> HTTPException:
    detail: dict[str, Any] = {"code": code, "message": message}
    if action:
        detail["action"] = action
    return HTTPException(status_code=status_code, detail=detail)


def session_workspace_root(session_id: str, *, for_write: bool = False) -> tuple[dict[str, Any], Path]:
    if not WORKSPACE_SECURE_OPEN_AVAILABLE:
        raise workspace_http_error(
            501,
            "workspace_secure_open_unavailable",
            "Secure workspace file access is unavailable on this host.",
        )
    sess = STORE.sessions.get(session_id)
    if not sess:
        raise workspace_http_error(404, "session_not_found", "Chat not found.")
    if for_write and bool(sess.get("archived")):
        raise workspace_http_error(409, "workspace_read_only", "Archived chats have read-only workspaces.")
    configured = str(sess.get("cwd") or "").strip()
    if not configured:
        raise workspace_http_error(
            409,
            "workspace_unavailable",
            "This chat does not have a working directory.",
            "Set its working directory in the inspector.",
        )
    try:
        root = Path(configured).expanduser().resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise workspace_http_error(
            409,
            "workspace_unavailable",
            f"The chat working directory is unavailable: {configured}",
            "Update the working directory in the inspector.",
        ) from exc
    if not root.is_dir():
        raise workspace_http_error(
            409,
            "workspace_unavailable",
            f"The chat working directory is not a directory: {configured}",
            "Update the working directory in the inspector.",
        )
    return sess, root


def normalize_workspace_path(value: str | None, *, allow_root: bool = False) -> str:
    raw = str(value or "")
    if "\x00" in raw:
        raise workspace_http_error(400, "invalid_workspace_path", "Workspace paths cannot contain NUL bytes.")
    if len(raw) > MAX_WORKSPACE_PATH_CHARS:
        raise workspace_http_error(400, "invalid_workspace_path", "Workspace path is too long.")
    portable = raw.replace("\\", "/") if os.name == "nt" else raw
    if portable.startswith("/") or re.match(r"^[A-Za-z]:/", portable):
        raise workspace_http_error(400, "invalid_workspace_path", "Workspace paths must be relative.")
    parts: list[str] = []
    for part in portable.split("/"):
        if part in ("", "."):
            continue
        if part == "..":
            raise workspace_http_error(400, "invalid_workspace_path", "Workspace paths cannot leave the chat working directory.")
        parts.append(part)
    normalized = "/".join(parts)
    if not normalized and not allow_root:
        raise workspace_http_error(400, "invalid_workspace_path", "A workspace file path is required.")
    return normalized


def workspace_open_flags(*, directory: bool = False) -> int:
    flags = os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW | os.O_NONBLOCK
    if directory:
        flags |= os.O_DIRECTORY
    return flags


def translate_workspace_os_error(exc: OSError, path: str, *, directory: bool = False) -> HTTPException:
    if exc.errno in {errno.ELOOP}:
        return workspace_http_error(403, "workspace_symlink_blocked", "Workspace symlinks cannot be opened.")
    if exc.errno in {errno.ENOENT}:
        noun = "directory" if directory else "file"
        return workspace_http_error(404, f"workspace_{noun}_not_found", f"Workspace {noun} not found: {path or '.'}")
    if exc.errno in {errno.ENOTDIR, errno.EISDIR}:
        return workspace_http_error(400, "invalid_workspace_path", f"Workspace path has the wrong type: {path or '.'}")
    if exc.errno in {errno.EACCES, errno.EPERM}:
        return workspace_http_error(403, "workspace_permission_denied", f"Permission denied: {path or '.'}")
    return workspace_http_error(500, "workspace_io_error", f"Could not access workspace path: {path or '.'}")


def open_workspace_directory_fd(root: Path, relative_path: str = "") -> int:
    flags = workspace_open_flags(directory=True)
    try:
        current = os.open(root, flags)
    except OSError as exc:
        raise translate_workspace_os_error(exc, str(root), directory=True) from exc
    try:
        for part in relative_path.split("/") if relative_path else ():
            try:
                next_fd = os.open(part, flags, dir_fd=current)
            except OSError as exc:
                raise translate_workspace_os_error(exc, relative_path, directory=True) from exc
            os.close(current)
            current = next_fd
        return current
    except Exception:
        os.close(current)
        raise


def open_workspace_parent_fd(root: Path, relative_path: str) -> tuple[int, str]:
    parts = relative_path.split("/")
    parent = "/".join(parts[:-1])
    return open_workspace_directory_fd(root, parent), parts[-1]


def workspace_revision(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def workspace_text_limit_exceeded(size: int) -> bool:
    return MAX_WORKSPACE_TEXT_BYTES > 0 and size > MAX_WORKSPACE_TEXT_BYTES


def workspace_text_bytes_capability() -> int:
    return MAX_WORKSPACE_TEXT_BYTES or WORKSPACE_UNLIMITED_TEXT_BYTES


def workspace_fd_revision(file_fd: int, max_bytes: int = 0) -> tuple[str, int]:
    """Hash an open file descriptor without retaining its contents in memory."""
    digest = hashlib.sha256()
    size = 0
    while True:
        chunk = os.read(file_fd, 1024 * 1024)
        if not chunk:
            break
        size += len(chunk)
        if max_bytes > 0 and size > max_bytes:
            raise OverflowError
        digest.update(chunk)
    return digest.hexdigest(), size


def read_workspace_text_fd(
    file_fd: int,
    normalized: str,
    error_prefix: Literal["workspace", "absolute"],
) -> tuple[str, str, int]:
    """Decode and hash a text file incrementally, retaining only text output."""
    digest = hashlib.sha256()
    decoder = codecs.getincrementaldecoder("utf-8")(errors="strict")
    content_chunks: list[str] = []
    size = 0
    while True:
        chunk = os.read(file_fd, 1024 * 1024)
        if not chunk:
            break
        size += len(chunk)
        if workspace_text_limit_exceeded(size):
            raise workspace_http_error(
                413,
                f"{error_prefix}_file_too_large",
                f"{normalized} exceeds the configured workspace text transfer limit.",
            )
        if b"\x00" in chunk:
            raise workspace_http_error(
                415,
                f"{error_prefix}_binary_file",
                f"{normalized} is binary and cannot be opened in the text editor.",
            )
        digest.update(chunk)
        try:
            content_chunks.append(decoder.decode(chunk, final=False))
        except UnicodeDecodeError as exc:
            raise workspace_http_error(
                415,
                f"{error_prefix}_encoding_unsupported",
                f"{normalized} is not UTF-8 text.",
            ) from exc
    try:
        content_chunks.append(decoder.decode(b"", final=True))
    except UnicodeDecodeError as exc:
        raise workspace_http_error(
            415,
            f"{error_prefix}_encoding_unsupported",
            f"{normalized} is not UTF-8 text.",
        ) from exc
    return "".join(content_chunks), digest.hexdigest(), size


def workspace_entry_revision(item_stat: os.stat_result) -> str:
    """Opaque revision for guarding metadata mutations against stale tree state."""
    identity = "\0".join(str(value) for value in (
        item_stat.st_dev,
        item_stat.st_ino,
        item_stat.st_mode,
        item_stat.st_nlink,
        item_stat.st_uid,
        item_stat.st_gid,
        item_stat.st_size,
        item_stat.st_mtime_ns,
        item_stat.st_ctime_ns,
    ))
    return hashlib.sha256(identity.encode("ascii")).hexdigest()


def validate_workspace_entry_revision(expected_revision: str, item_stat: os.stat_result, path: str) -> None:
    if not re.fullmatch(r"[0-9a-fA-F]{64}", expected_revision or ""):
        raise workspace_http_error(
            400,
            "invalid_workspace_entry_revision",
            "A valid workspace entry revision is required.",
        )
    actual_revision = workspace_entry_revision(item_stat)
    if not hmac.compare_digest(actual_revision, expected_revision.lower()):
        raise workspace_http_error(
            409,
            "workspace_entry_conflict",
            f"{path} changed on disk. Refresh the file explorer and try again.",
        )


def workspace_entry_kind(item_stat: os.stat_result, path: str) -> str:
    if stat.S_ISDIR(item_stat.st_mode):
        return "directory"
    if stat.S_ISREG(item_stat.st_mode):
        return "file"
    if stat.S_ISLNK(item_stat.st_mode):
        return "symlink"
    raise workspace_http_error(
        400,
        "workspace_entry_type_unsupported",
        f"Workspace entry type cannot be changed: {path}",
    )


def workspace_entry(relative_path: str, name: str, item_stat: os.stat_result) -> dict[str, Any] | None:
    path = f"{relative_path}/{name}" if relative_path else name
    if stat.S_ISDIR(item_stat.st_mode):
        kind = "directory"
    elif stat.S_ISREG(item_stat.st_mode):
        kind = "file"
    elif stat.S_ISLNK(item_stat.st_mode):
        kind = "symlink"
    else:
        return None
    return {
        "name": name,
        "path": path,
        "kind": kind,
        "size": int(item_stat.st_size) if kind == "file" else None,
        "mtime_ns": int(item_stat.st_mtime_ns),
        "hidden": name.startswith("."),
        "writable": kind == "file" and bool(item_stat.st_mode & 0o222),
        "revision": workspace_entry_revision(item_stat),
    }


def workspace_info_sync(session_id: str) -> dict[str, Any]:
    sess, root = session_workspace_root(session_id)
    return {
        "root": str(root),
        "name": root.name or str(root),
        "read_only": bool(sess.get("archived")),
        "capability_version": 6 if WORKSPACE_MUTATIONS_AVAILABLE else 1,
        "max_text_file_bytes": workspace_text_bytes_capability(),
        "max_preview_file_bytes": MAX_WORKSPACE_PREVIEW_BYTES,
        "preview_media_types": sorted(set(WORKSPACE_PREVIEW_MEDIA_TYPES.values())),
    }


def list_workspace_entries_sync(
    session_id: str,
    relative_path: str,
    offset: int,
    limit: int,
) -> dict[str, Any]:
    sess, root = session_workspace_root(session_id)
    normalized = normalize_workspace_path(relative_path, allow_root=True)
    directory_fd = open_workspace_directory_fd(root, normalized)
    try:
        records: list[dict[str, Any]] = []
        for name in os.listdir(directory_fd):
            try:
                item_stat = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
            except FileNotFoundError:
                continue
            except OSError as exc:
                if exc.errno in {errno.EACCES, errno.EPERM}:
                    continue
                raise translate_workspace_os_error(exc, f"{normalized}/{name}".strip("/")) from exc
            record = workspace_entry(normalized, name, item_stat)
            if record:
                if bool(sess.get("archived")):
                    record["writable"] = False
                records.append(record)
    finally:
        os.close(directory_fd)
    records.sort(key=lambda item: (item["kind"] != "directory", str(item["name"]).casefold(), str(item["name"])))
    total = len(records)
    page = records[offset:offset + limit]
    return {
        "root": str(root),
        "path": normalized,
        "entries": page,
        "total": total,
        "offset": offset,
        "limit": limit,
        "has_more": offset + len(page) < total,
    }


def read_workspace_file_sync(session_id: str, relative_path: str) -> dict[str, Any]:
    sess, root = session_workspace_root(session_id)
    normalized = normalize_workspace_path(relative_path)
    parent_fd, name = open_workspace_parent_fd(root, normalized)
    file_fd = -1
    try:
        try:
            file_fd = os.open(name, workspace_open_flags(), dir_fd=parent_fd)
        except OSError as exc:
            raise translate_workspace_os_error(exc, normalized) from exc
        item_stat = os.fstat(file_fd)
        if not stat.S_ISREG(item_stat.st_mode):
            raise workspace_http_error(400, "workspace_not_regular_file", f"Not a regular workspace file: {normalized}")
        if workspace_text_limit_exceeded(item_stat.st_size):
            raise workspace_http_error(
                413,
                "workspace_file_too_large",
                f"{normalized} exceeds the configured workspace text transfer limit.",
            )
        content, revision, size = read_workspace_text_fd(file_fd, normalized, "workspace")
        return {
            "root": str(root),
            "path": normalized,
            "name": name,
            "content": content,
            "revision": revision,
            "size": size,
            "mtime_ns": int(item_stat.st_mtime_ns),
            "writable": not bool(sess.get("archived")) and bool(item_stat.st_mode & 0o222),
        }
    finally:
        if file_fd >= 0:
            os.close(file_fd)
        os.close(parent_fd)


def normalize_absolute_file_path(value: str | None) -> tuple[Path, str, str]:
    """Validate one explicit, native absolute path for direct file access.

    This is deliberately separate from workspace normalization. It accepts no
    relative, dot-segment, or lexically non-canonical paths, so callers cannot
    smuggle traversal semantics into a direct-read request. A leading ``~/``
    is the one supported shorthand: it expands on AgentsServer so it always
    refers to the remote server account's home rather than Electron's host.
    """
    raw = str(value or "")
    if "\x00" in raw:
        raise workspace_http_error(400, "invalid_absolute_file_path", "Absolute file paths cannot contain NUL bytes.")
    if len(raw) > MAX_WORKSPACE_PATH_CHARS:
        raise workspace_http_error(400, "invalid_absolute_file_path", "Absolute file path is too long.")
    if raw.startswith("~/"):
        home = os.path.normpath(str(Path.home()))
        if not os.path.isabs(home):
            raise workspace_http_error(500, "workspace_home_unavailable", "The server user's home directory is unavailable.")
        suffix = raw[2:].replace("/", os.sep) if os.name == "nt" else raw[2:]
        trimmed_home = home.rstrip("/\\")
        raw = f"{trimmed_home}{os.sep}{suffix}" if trimmed_home else f"{os.sep}{suffix}"
        if len(raw) > MAX_WORKSPACE_PATH_CHARS:
            raise workspace_http_error(400, "invalid_absolute_file_path", "Absolute file path is too long.")
    if not os.path.isabs(raw):
        raise workspace_http_error(400, "invalid_absolute_file_path", "An absolute file path is required.")
    if os.name != "nt" and raw.startswith("//"):
        raise workspace_http_error(400, "invalid_absolute_file_path", "The absolute file path must use one filesystem root.")
    if os.path.normpath(raw) != raw:
        raise workspace_http_error(
            400,
            "invalid_absolute_file_path",
            "Absolute file paths must be canonical and cannot contain dot segments or repeated separators.",
        )
    absolute = Path(raw)
    parts = absolute.parts
    if not parts or not absolute.anchor or len(parts) < 2:
        raise workspace_http_error(400, "invalid_absolute_file_path", "An absolute file path is required.")
    relative = "/".join(parts[1:])
    if not relative:
        raise workspace_http_error(400, "invalid_absolute_file_path", "An absolute file path is required.")
    return Path(absolute.anchor), relative, raw


def read_absolute_file_sync(session_id: str, absolute_path: str) -> dict[str, Any]:
    """Read one explicitly named absolute UTF-8 file without enumerating its parent."""
    if not WORKSPACE_SECURE_OPEN_AVAILABLE:
        raise workspace_http_error(
            501,
            "workspace_secure_open_unavailable",
            "Secure absolute file access is unavailable on this host.",
        )
    sess = STORE.sessions.get(session_id)
    if not sess:
        raise workspace_http_error(404, "session_not_found", "Chat not found.")
    root, relative, normalized = normalize_absolute_file_path(absolute_path)
    parent_fd, name = open_workspace_parent_fd(root, relative)
    file_fd = -1
    try:
        try:
            file_fd = os.open(name, workspace_open_flags(), dir_fd=parent_fd)
        except OSError as exc:
            raise translate_workspace_os_error(exc, normalized) from exc
        item_stat = os.fstat(file_fd)
        if not stat.S_ISREG(item_stat.st_mode):
            raise workspace_http_error(400, "absolute_not_regular_file", f"Not a regular file: {normalized}")
        if workspace_text_limit_exceeded(item_stat.st_size):
            raise workspace_http_error(
                413,
                "absolute_file_too_large",
                f"{normalized} exceeds the configured workspace text transfer limit.",
            )
        content, revision, size = read_workspace_text_fd(file_fd, normalized, "absolute")
        return {
            "root": str(root),
            "path": normalized,
            "name": name,
            "content": content,
            "revision": revision,
            "size": size,
            "mtime_ns": int(item_stat.st_mtime_ns),
            "writable": (
                WORKSPACE_MUTATIONS_AVAILABLE
                and not bool(sess.get("archived"))
                and bool(item_stat.st_mode & 0o222)
                and item_stat.st_nlink == 1
            ),
            "scope": "absolute",
        }
    finally:
        if file_fd >= 0:
            os.close(file_fd)
        os.close(parent_fd)


def workspace_preview_media_type(relative_path: str) -> str:
    media_type = WORKSPACE_PREVIEW_MEDIA_TYPES.get(Path(relative_path).suffix.lower())
    if media_type is None:
        raise workspace_http_error(
            415,
            "workspace_preview_unsupported",
            (
                f"{relative_path} is not a supported image or PDF preview. "
                "SVG and text files must be opened in the text editor."
            ),
        )
    return media_type


def open_workspace_preview_sync(session_id: str, relative_path: str) -> dict[str, Any]:
    """Securely open one preview resource and transfer ownership of its file descriptor."""
    _, root = session_workspace_root(session_id)
    normalized = normalize_workspace_path(relative_path)
    parent_fd, name = open_workspace_parent_fd(root, normalized)
    file_fd = -1
    try:
        try:
            file_fd = os.open(name, workspace_open_flags(), dir_fd=parent_fd)
        except OSError as exc:
            raise translate_workspace_os_error(exc, normalized) from exc
        item_stat = os.fstat(file_fd)
        if not stat.S_ISREG(item_stat.st_mode):
            raise workspace_http_error(
                400,
                "workspace_not_regular_file",
                f"Not a regular workspace file: {normalized}",
            )
        if item_stat.st_size > MAX_WORKSPACE_PREVIEW_BYTES:
            raise workspace_http_error(
                413,
                "workspace_preview_too_large",
                (
                    f"{normalized} is larger than the "
                    f"{MAX_WORKSPACE_PREVIEW_BYTES // (1024 * 1024)} MiB preview limit."
                ),
            )
        media_type = workspace_preview_media_type(normalized)
        result = {
            "file_fd": file_fd,
            "root": str(root),
            "path": normalized,
            "name": name,
            "media_type": media_type,
            "revision": workspace_entry_revision(item_stat),
            "size": int(item_stat.st_size),
            "mtime_ns": int(item_stat.st_mtime_ns),
        }
        file_fd = -1
        return result
    finally:
        if file_fd >= 0:
            os.close(file_fd)
        os.close(parent_fd)


def open_workspace_download_sync(session_id: str, relative_path: str) -> dict[str, Any]:
    """Securely open one workspace file for an explicit user download."""
    _, root = session_workspace_root(session_id)
    normalized = normalize_workspace_path(relative_path)
    parent_fd, name = open_workspace_parent_fd(root, normalized)
    file_fd = -1
    try:
        try:
            file_fd = os.open(name, workspace_open_flags(), dir_fd=parent_fd)
        except OSError as exc:
            raise translate_workspace_os_error(exc, normalized) from exc
        item_stat = os.fstat(file_fd)
        if not stat.S_ISREG(item_stat.st_mode):
            raise workspace_http_error(
                400,
                "workspace_not_regular_file",
                f"Not a regular workspace file: {normalized}",
            )
        result = {
            "file_fd": file_fd,
            "root": str(root),
            "path": normalized,
            "name": name,
            "revision": workspace_entry_revision(item_stat),
            "size": int(item_stat.st_size),
            "mtime_ns": int(item_stat.st_mtime_ns),
        }
        file_fd = -1
        return result
    finally:
        if file_fd >= 0:
            os.close(file_fd)
        os.close(parent_fd)


def workspace_preview_range_error(size: int) -> HTTPException:
    return HTTPException(
        status_code=416,
        detail={
            "code": "workspace_preview_range_unsatisfiable",
            "message": "The requested byte range cannot be served.",
        },
        headers={
            "Accept-Ranges": "bytes",
            "Cache-Control": "no-store",
            "Content-Range": f"bytes */{size}",
            "X-Content-Type-Options": "nosniff",
        },
    )


def parse_workspace_preview_range(value: str | None, size: int) -> tuple[int, int] | None:
    """Parse one HTTP byte range and return an inclusive start/end pair."""
    if value is None or not value.strip():
        return None
    match = re.fullmatch(r"bytes=(\d{0,20})-(\d{0,20})", value.strip(), flags=re.IGNORECASE)
    if match is None or size <= 0:
        raise workspace_preview_range_error(size)
    start_text, end_text = match.groups()
    if not start_text and not end_text:
        raise workspace_preview_range_error(size)
    if not start_text:
        suffix_length = int(end_text)
        if suffix_length <= 0:
            raise workspace_preview_range_error(size)
        start = max(0, size - suffix_length)
        return start, size - 1
    start = int(start_text)
    if start >= size:
        raise workspace_preview_range_error(size)
    if not end_text:
        return start, size - 1
    end = int(end_text)
    if end < start:
        raise workspace_preview_range_error(size)
    return start, min(end, size - 1)


def stream_workspace_preview(file_fd: int, start: int, length: int):
    """Yield a bounded byte window from an already-validated workspace file."""
    try:
        os.lseek(file_fd, start, os.SEEK_SET)
        remaining = length
        while remaining > 0:
            chunk = os.read(file_fd, min(256 * 1024, remaining))
            if not chunk:
                break
            remaining -= len(chunk)
            yield chunk
    finally:
        os.close(file_fd)


def write_all(file_fd: int, data: bytes) -> None:
    offset = 0
    while offset < len(data):
        written = os.write(file_fd, data[offset:])
        if written <= 0:
            raise OSError(errno.EIO, "short workspace write")
        offset += written


def workspace_write_lock(root: Path, relative_path: str) -> threading.Lock:
    # Key by the lexical destination rather than the API's root/relative
    # representation. The same file can be addressed through the workspace
    # route or the explicit absolute route and must share one process lock.
    destination = os.path.normcase(os.path.normpath(str(root.joinpath(*relative_path.split("/")))))
    key = hashlib.sha256(destination.encode("utf-8", errors="surrogatepass")).digest()
    return WORKSPACE_WRITE_LOCKS[int.from_bytes(key[:2], "big") % len(WORKSPACE_WRITE_LOCKS)]


@contextmanager
def workspace_write_locks(root: Path, *relative_paths: str):
    locks_by_identity = {
        id(lock): lock
        for lock in (workspace_write_lock(root, path) for path in relative_paths)
    }
    locks = [locks_by_identity[key] for key in sorted(locks_by_identity)]
    for lock in locks:
        lock.acquire()
    try:
        yield
    finally:
        for lock in reversed(locks):
            lock.release()


def preserve_workspace_metadata(source_fd: int, destination_fd: int, source_stat: os.stat_result) -> None:
    os.fchmod(destination_fd, stat.S_IMODE(source_stat.st_mode))
    with suppress(PermissionError):
        os.fchown(destination_fd, source_stat.st_uid, source_stat.st_gid)
    if not all(hasattr(os, name) for name in ("listxattr", "getxattr", "setxattr")):
        return
    try:
        names = os.listxattr(source_fd)
    except OSError:
        return
    for attribute in names:
        try:
            os.setxattr(destination_fd, attribute, os.getxattr(source_fd, attribute))
        except OSError:
            logger.warning("could not preserve workspace xattr %s", attribute)


def write_workspace_file_sync(
    session_id: str,
    relative_path: str,
    content: str,
    expected_revision: str,
) -> dict[str, Any]:
    _, root = session_workspace_root(session_id, for_write=True)
    normalized = normalize_workspace_path(relative_path)
    with workspace_write_lock(root, normalized):
        return write_workspace_file_locked(root, normalized, content, expected_revision)


def write_absolute_file_sync(
    session_id: str,
    absolute_path: str,
    content: str,
    expected_revision: str,
) -> dict[str, Any]:
    """Revision-check and atomically replace one explicitly named absolute file.

    This grants no directory enumeration or create/rename/delete authority. The
    shared writer retains no-follow opens, regular-file and hard-link checks,
    metadata preservation, a second pre-replace revision check, fsync, and an
    atomic same-directory replace.
    """
    if not WORKSPACE_MUTATIONS_AVAILABLE:
        raise workspace_http_error(
            501,
            "workspace_mutations_unavailable",
            "Secure absolute file editing is unavailable on this host.",
        )
    sess = STORE.sessions.get(session_id)
    if not sess:
        raise workspace_http_error(404, "session_not_found", "Chat not found.")
    if bool(sess.get("archived")):
        raise workspace_http_error(409, "workspace_read_only", "Archived chats cannot edit files.")
    root, relative, normalized = normalize_absolute_file_path(absolute_path)
    with workspace_write_lock(root, relative):
        result = write_workspace_file_locked(root, relative, content, expected_revision)
    return {
        **result,
        "path": normalized,
        "scope": "absolute",
    }


def write_workspace_file_locked(
    root: Path,
    relative_path: str,
    content: str,
    expected_revision: str,
) -> dict[str, Any]:
    normalized = normalize_workspace_path(relative_path)
    if not re.fullmatch(r"[0-9a-fA-F]{64}", expected_revision or ""):
        raise workspace_http_error(400, "invalid_workspace_revision", "A valid workspace file revision is required.")
    data = content.encode("utf-8")
    if b"\x00" in data:
        raise workspace_http_error(415, "workspace_binary_file", "Edited content cannot contain NUL bytes.")
    if workspace_text_limit_exceeded(len(data)):
        raise workspace_http_error(413, "workspace_file_too_large", "Edited content exceeds the configured workspace text transfer limit.")
    parent_fd, name = open_workspace_parent_fd(root, normalized)
    current_fd = -1
    temp_fd = -1
    temp_name = f".{name}.agentsdock-{uuid.uuid4().hex}.tmp"
    try:
        try:
            current_fd = os.open(name, workspace_open_flags(), dir_fd=parent_fd)
        except OSError as exc:
            raise translate_workspace_os_error(exc, normalized) from exc
        current_stat = os.fstat(current_fd)
        if not stat.S_ISREG(current_stat.st_mode):
            raise workspace_http_error(400, "workspace_not_regular_file", f"Not a regular workspace file: {normalized}")
        if current_stat.st_nlink > 1:
            raise workspace_http_error(
                409,
                "workspace_hard_link_blocked",
                f"{normalized} has multiple hard links and cannot be replaced safely.",
            )
        if not bool(current_stat.st_mode & 0o222):
            raise workspace_http_error(403, "workspace_permission_denied", f"Workspace file is read-only: {normalized}")
        if workspace_text_limit_exceeded(current_stat.st_size):
            raise workspace_http_error(
                413,
                "workspace_file_too_large",
                f"{normalized} exceeds the workspace text transfer limit.",
            )
        try:
            actual_revision, _ = workspace_fd_revision(current_fd, MAX_WORKSPACE_TEXT_BYTES)
        except OverflowError:
            raise workspace_http_error(
                413,
                "workspace_file_too_large",
                f"{normalized} exceeds the workspace text transfer limit.",
            ) from None
        if not hmac.compare_digest(actual_revision, expected_revision.lower()):
            raise workspace_http_error(
                409,
                "workspace_file_conflict",
                f"{normalized} changed on disk. Reload it before saving your edits.",
            )
        try:
            temp_fd = os.open(
                temp_name,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
                stat.S_IMODE(current_stat.st_mode),
                dir_fd=parent_fd,
            )
            write_all(temp_fd, data)
            preserve_workspace_metadata(current_fd, temp_fd, current_stat)
            os.fsync(temp_fd)
            os.close(temp_fd)
            temp_fd = -1
            latest_fd = -1
            try:
                latest_fd = os.open(name, workspace_open_flags(), dir_fd=parent_fd)
                latest_stat = os.fstat(latest_fd)
                if not stat.S_ISREG(latest_stat.st_mode):
                    raise workspace_http_error(409, "workspace_file_conflict", f"{normalized} changed while it was being saved.")
                try:
                    latest_revision, _ = workspace_fd_revision(latest_fd, MAX_WORKSPACE_TEXT_BYTES)
                except OverflowError:
                    raise workspace_http_error(
                        409,
                        "workspace_file_conflict",
                        f"{normalized} changed while it was being saved.",
                    ) from None
            finally:
                if latest_fd >= 0:
                    os.close(latest_fd)
            if (
                latest_stat.st_dev != current_stat.st_dev
                or latest_stat.st_ino != current_stat.st_ino
                or stat.S_IMODE(latest_stat.st_mode) != stat.S_IMODE(current_stat.st_mode)
                or latest_stat.st_uid != current_stat.st_uid
                or latest_stat.st_gid != current_stat.st_gid
                or latest_stat.st_nlink != current_stat.st_nlink
                or not hmac.compare_digest(latest_revision, actual_revision)
            ):
                raise workspace_http_error(
                    409,
                    "workspace_file_conflict",
                    f"{normalized} changed while it was being saved. Reload it and try again.",
                )
            os.replace(temp_name, name, src_dir_fd=parent_fd, dst_dir_fd=parent_fd)
            try:
                os.fsync(parent_fd)
            except OSError as exc:
                logger.warning("workspace directory fsync failed after saving %s: %s", normalized, exc)
        except HTTPException:
            raise
        except OSError as exc:
            raise translate_workspace_os_error(exc, normalized) from exc
        updated_stat = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        return {
            "root": str(root),
            "path": normalized,
            "name": name,
            "content": content,
            "revision": workspace_revision(data),
            "size": len(data),
            "mtime_ns": int(updated_stat.st_mtime_ns),
            "writable": bool(updated_stat.st_mode & 0o222),
        }
    finally:
        if current_fd >= 0:
            os.close(current_fd)
        if temp_fd >= 0:
            os.close(temp_fd)
        with suppress(OSError):
            os.unlink(temp_name, dir_fd=parent_fd)
        os.close(parent_fd)


def normalize_workspace_entry_name(value: str, source_path: str) -> str:
    name = str(value or "")
    if "\x00" in name:
        raise workspace_http_error(400, "invalid_workspace_name", "Workspace names cannot contain NUL bytes.")
    if not name or name in {".", ".."} or "/" in name or (os.name == "nt" and "\\" in name):
        raise workspace_http_error(400, "invalid_workspace_name", "A single workspace entry name is required.")
    parent = source_path.rsplit("/", 1)[0] if "/" in source_path else ""
    destination = f"{parent}/{name}" if parent else name
    if len(destination) > MAX_WORKSPACE_PATH_CHARS:
        raise workspace_http_error(400, "invalid_workspace_path", "Workspace path is too long.")
    return name


def fsync_workspace_directory(directory_fd: int, path: str) -> None:
    try:
        os.fsync(directory_fd)
    except OSError as exc:
        logger.warning("workspace directory fsync failed after mutating %s: %s", path, exc)


def translate_workspace_create_error(exc: OSError, path: str, kind: str) -> HTTPException:
    if exc.errno in {errno.EEXIST, errno.ENOTEMPTY}:
        return workspace_http_error(409, "workspace_entry_exists", f"Workspace entry already exists: {path}")
    if exc.errno == errno.ENOENT:
        return workspace_http_error(
            404,
            "workspace_directory_not_found",
            f"Workspace parent directory not found: {path.rsplit('/', 1)[0] or '.'}",
        )
    if exc.errno in {errno.EACCES, errno.EPERM, errno.EROFS}:
        return workspace_http_error(403, "workspace_permission_denied", f"Permission denied: {path}")
    if exc.errno in {errno.ENOTDIR, errno.EISDIR}:
        return workspace_http_error(400, "invalid_workspace_path", f"Workspace path has the wrong type: {path}")
    if exc.errno == errno.ELOOP:
        return workspace_http_error(403, "workspace_symlink_blocked", "Workspace symlinks cannot be opened.")
    if exc.errno == errno.ENAMETOOLONG:
        return workspace_http_error(400, "invalid_workspace_path", "Workspace path is too long.")
    if exc.errno in {errno.ENOSPC, getattr(errno, "EDQUOT", errno.ENOSPC)}:
        return workspace_http_error(
            507,
            "workspace_storage_full",
            f"Not enough storage is available to create the workspace {kind}: {path}",
        )
    return workspace_http_error(500, "workspace_io_error", f"Could not create workspace {kind}: {path}")


def workspace_create_partial_success_error(path: str) -> HTTPException:
    return workspace_http_error(
        500,
        "workspace_create_partial_success",
        (
            f"AgentsDock created or changed {path}, but could not finish validating the operation. "
            "Refresh the file explorer and inspect the path before trying again."
        ),
    )


def create_workspace_entry_sync(
    session_id: str,
    relative_path: str,
    kind: Literal["file", "directory"],
) -> dict[str, Any]:
    _, root = session_workspace_root(session_id, for_write=True)
    normalized = normalize_workspace_path(relative_path)
    if kind not in {"file", "directory"}:
        raise workspace_http_error(
            400,
            "invalid_workspace_entry_kind",
            "Workspace entry kind must be file or directory.",
        )
    parent_path = normalized.rsplit("/", 1)[0] if "/" in normalized else ""
    with workspace_write_lock(root, normalized):
        parent_fd, name = open_workspace_parent_fd(root, normalized)
        created_fd = -1
        created = False
        created_stat: os.stat_result | None = None
        try:
            try:
                if kind == "file":
                    created_fd = os.open(
                        name,
                        (
                            os.O_WRONLY
                            | os.O_CREAT
                            | os.O_EXCL
                            | getattr(os, "O_CLOEXEC", 0)
                            | getattr(os, "O_NOFOLLOW", 0)
                        ),
                        0o666,
                        dir_fd=parent_fd,
                    )
                    created = True
                    created_stat = os.fstat(created_fd)
                    if not stat.S_ISREG(created_stat.st_mode):
                        raise workspace_http_error(
                            409,
                            "workspace_entry_conflict",
                            f"{normalized} changed while it was being created.",
                        )
                    os.fsync(created_fd)
                else:
                    os.mkdir(name, 0o777, dir_fd=parent_fd)
                    created = True
                    created_stat = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
                    if not stat.S_ISDIR(created_stat.st_mode):
                        raise workspace_http_error(
                            409,
                            "workspace_entry_conflict",
                            f"{normalized} changed while it was being created.",
                        )
                    created_fd = os.open(name, workspace_open_flags(directory=True), dir_fd=parent_fd)
                    opened_stat = os.fstat(created_fd)
                    if (
                        opened_stat.st_dev != created_stat.st_dev
                        or opened_stat.st_ino != created_stat.st_ino
                    ):
                        raise workspace_http_error(
                            409,
                            "workspace_entry_conflict",
                            f"{normalized} changed while it was being created.",
                        )
                    created_stat = opened_stat
                    fsync_workspace_directory(created_fd, normalized)
            except HTTPException:
                raise
            except OSError as exc:
                raise translate_workspace_create_error(exc, normalized, kind) from exc

            try:
                visible_stat = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except OSError as exc:
                raise translate_workspace_create_error(exc, normalized, kind) from exc
            if (
                created_stat is None
                or visible_stat.st_dev != created_stat.st_dev
                or visible_stat.st_ino != created_stat.st_ino
                or workspace_entry_kind(visible_stat, normalized) != kind
            ):
                raise workspace_http_error(
                    409,
                    "workspace_entry_conflict",
                    f"{normalized} changed while it was being created.",
                )
            fsync_workspace_directory(parent_fd, normalized)
            entry = workspace_entry(parent_path, name, visible_stat)
            if entry is None:
                raise workspace_http_error(
                    400,
                    "workspace_entry_type_unsupported",
                    f"Workspace entry type cannot be created: {normalized}",
                )
            result: dict[str, Any] = {
                "root": str(root),
                "entry": entry,
            }
            if kind == "file":
                result["file"] = {
                    "root": str(root),
                    "path": normalized,
                    "name": name,
                    "content": "",
                    "revision": workspace_revision(b""),
                    "size": 0,
                    "mtime_ns": int(visible_stat.st_mtime_ns),
                    "writable": bool(visible_stat.st_mode & 0o222),
                }
            return result
        except Exception as exc:
            if created:
                logger.error("workspace create may have partially succeeded for %s: %s", normalized, exc)
                raise workspace_create_partial_success_error(normalized) from exc
            raise
        finally:
            if created_fd >= 0:
                os.close(created_fd)
            os.close(parent_fd)


def atomic_rename_workspace_entry(parent_fd: int, old_name: str, new_name: str, path: str) -> None:
    if WORKSPACE_ATOMIC_RENAME is None:
        raise workspace_http_error(
            501,
            "workspace_atomic_rename_unavailable",
            "Atomic workspace rename is unavailable on this host.",
        )
    ctypes.set_errno(0)
    result = WORKSPACE_ATOMIC_RENAME(
        parent_fd,
        os.fsencode(old_name),
        parent_fd,
        os.fsencode(new_name),
        WORKSPACE_ATOMIC_RENAME_FLAG,
    )
    if result == 0:
        return
    error = ctypes.get_errno()
    if error in {errno.EEXIST, errno.ENOTEMPTY}:
        raise workspace_http_error(409, "workspace_entry_exists", f"Workspace entry already exists: {new_name}")
    if error == errno.ENOENT:
        raise workspace_http_error(404, "workspace_entry_not_found", f"Workspace entry not found: {path}")
    if error in {errno.EACCES, errno.EPERM, errno.EROFS}:
        raise workspace_http_error(403, "workspace_permission_denied", f"Permission denied: {path}")
    if error == errno.ENAMETOOLONG:
        raise workspace_http_error(400, "invalid_workspace_name", "Workspace entry name is too long.")
    if error == errno.EXDEV:
        raise workspace_http_error(409, "workspace_cross_device_move", "Workspace entries cannot be moved across filesystems.")
    if error in {errno.ENOSYS, errno.EINVAL, getattr(errno, "ENOTSUP", errno.EINVAL)}:
        raise workspace_http_error(
            501,
            "workspace_atomic_rename_unavailable",
            "Atomic workspace rename is unavailable on this filesystem.",
        )
    if error == errno.EBUSY:
        raise workspace_http_error(409, "workspace_entry_busy", f"Workspace entry is busy: {path}")
    raise workspace_http_error(500, "workspace_io_error", f"Could not rename workspace entry: {path}")


def workspace_rename_identity(item_stat: os.stat_result) -> tuple[int, ...]:
    """Metadata that must survive a rename, excluding ctime changed by rename itself."""
    return (
        item_stat.st_dev,
        item_stat.st_ino,
        item_stat.st_mode,
        item_stat.st_nlink,
        item_stat.st_uid,
        item_stat.st_gid,
        item_stat.st_size,
        item_stat.st_mtime_ns,
    )


def rollback_workspace_rename(
    parent_fd: int,
    old_name: str,
    new_name: str,
    source_path: str,
    destination_path: str,
) -> None:
    """Put a raced rename back before reporting the revision conflict."""
    try:
        atomic_rename_workspace_entry(parent_fd, new_name, old_name, destination_path)
        fsync_workspace_directory(parent_fd, source_path)
    except HTTPException as exc:
        logger.critical(
            "workspace rename rollback failed for %s -> %s: %s",
            source_path,
            destination_path,
            exc.detail,
        )
        raise workspace_http_error(
            500,
            "workspace_rename_rollback_failed",
            (
                f"{source_path} changed while it was being renamed, and the server "
                "could not safely restore its original path. Refresh the file explorer "
                "and inspect both paths before trying again."
            ),
        ) from exc


def rename_workspace_entry_sync(
    session_id: str,
    relative_path: str,
    new_name: str,
    expected_revision: str,
) -> dict[str, Any]:
    _, root = session_workspace_root(session_id, for_write=True)
    normalized = normalize_workspace_path(relative_path)
    old_name = normalized.rsplit("/", 1)[-1]
    clean_name = normalize_workspace_entry_name(new_name, normalized)
    if clean_name == old_name:
        raise workspace_http_error(400, "workspace_entry_unchanged", "The workspace entry already has that name.")
    parent_path = normalized.rsplit("/", 1)[0] if "/" in normalized else ""
    destination_path = f"{parent_path}/{clean_name}" if parent_path else clean_name
    with workspace_write_locks(root, normalized, destination_path):
        parent_fd = open_workspace_directory_fd(root, parent_path)
        try:
            try:
                source_stat = os.stat(old_name, dir_fd=parent_fd, follow_symlinks=False)
            except OSError as exc:
                if exc.errno == errno.ENOENT:
                    raise workspace_http_error(
                        404,
                        "workspace_entry_not_found",
                        f"Workspace entry not found: {normalized}",
                    ) from exc
                raise translate_workspace_os_error(exc, normalized) from exc
            workspace_entry_kind(source_stat, normalized)
            validate_workspace_entry_revision(expected_revision, source_stat, normalized)
            atomic_rename_workspace_entry(parent_fd, old_name, clean_name, normalized)
            try:
                updated_stat = os.stat(clean_name, dir_fd=parent_fd, follow_symlinks=False)
            except OSError as exc:
                raise translate_workspace_os_error(exc, destination_path) from exc
            if workspace_rename_identity(updated_stat) != workspace_rename_identity(source_stat):
                rollback_workspace_rename(
                    parent_fd,
                    old_name,
                    clean_name,
                    normalized,
                    destination_path,
                )
                raise workspace_http_error(
                    409,
                    "workspace_entry_conflict",
                    f"{normalized} changed while it was being renamed.",
                )
            fsync_workspace_directory(parent_fd, destination_path)
            entry = workspace_entry(parent_path, clean_name, updated_stat)
            if entry is None:
                raise workspace_http_error(
                    400,
                    "workspace_entry_type_unsupported",
                    f"Workspace entry type cannot be changed: {destination_path}",
                )
            return {
                "root": str(root),
                "previous_path": normalized,
                "entry": entry,
            }
        finally:
            os.close(parent_fd)


def ensure_workspace_device(item_stat: os.stat_result, root_device: int, path: str) -> None:
    if item_stat.st_dev != root_device:
        raise workspace_http_error(
            409,
            "workspace_cross_device_delete",
            f"Recursive deletion cannot cross a mounted filesystem: {path}",
        )


def open_workspace_delete_directory(
    parent_fd: int,
    name: str,
    path: str,
    root_device: int,
) -> tuple[int, os.stat_result]:
    try:
        directory_fd = os.open(name, workspace_open_flags(directory=True), dir_fd=parent_fd)
    except OSError as exc:
        raise translate_workspace_os_error(exc, path, directory=True) from exc
    try:
        directory_stat = os.fstat(directory_fd)
        if not stat.S_ISDIR(directory_stat.st_mode):
            raise workspace_http_error(
                409,
                "workspace_entry_conflict",
                f"{path} changed while it was being deleted.",
            )
        ensure_workspace_device(directory_stat, root_device, path)
        return directory_fd, directory_stat
    except Exception:
        os.close(directory_fd)
        raise


def validate_workspace_delete_tree(directory_fd: int, relative_path: str, root_device: int) -> None:
    try:
        names = os.listdir(directory_fd)
    except OSError as exc:
        raise translate_workspace_os_error(exc, relative_path, directory=True) from exc
    for name in names:
        path = f"{relative_path}/{name}"
        try:
            item_stat = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        except FileNotFoundError:
            continue
        except OSError as exc:
            raise translate_workspace_os_error(exc, path) from exc
        ensure_workspace_device(item_stat, root_device, path)
        if not stat.S_ISDIR(item_stat.st_mode):
            continue
        child_fd, child_stat = open_workspace_delete_directory(directory_fd, name, path, root_device)
        try:
            if child_stat.st_ino != item_stat.st_ino or child_stat.st_dev != item_stat.st_dev:
                raise workspace_http_error(
                    409,
                    "workspace_entry_conflict",
                    f"{path} changed while it was being deleted.",
                )
            validate_workspace_delete_tree(child_fd, path, root_device)
        finally:
            os.close(child_fd)


def remove_workspace_tree_contents(directory_fd: int, relative_path: str, root_device: int) -> None:
    try:
        names = os.listdir(directory_fd)
    except OSError as exc:
        raise translate_workspace_os_error(exc, relative_path, directory=True) from exc
    for name in names:
        path = f"{relative_path}/{name}"
        try:
            item_stat = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        except FileNotFoundError:
            continue
        except OSError as exc:
            raise translate_workspace_os_error(exc, path) from exc
        ensure_workspace_device(item_stat, root_device, path)
        if stat.S_ISDIR(item_stat.st_mode):
            child_fd, child_stat = open_workspace_delete_directory(directory_fd, name, path, root_device)
            try:
                if child_stat.st_ino != item_stat.st_ino or child_stat.st_dev != item_stat.st_dev:
                    raise workspace_http_error(
                        409,
                        "workspace_entry_conflict",
                        f"{path} changed while it was being deleted.",
                    )
                remove_workspace_tree_contents(child_fd, path, root_device)
                try:
                    latest_stat = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
                except OSError as exc:
                    raise translate_workspace_os_error(exc, path, directory=True) from exc
                if latest_stat.st_ino != child_stat.st_ino or latest_stat.st_dev != child_stat.st_dev:
                    raise workspace_http_error(
                        409,
                        "workspace_entry_conflict",
                        f"{path} changed while it was being deleted.",
                    )
                try:
                    os.rmdir(name, dir_fd=directory_fd)
                except OSError as exc:
                    raise translate_workspace_delete_error(exc, path, directory=True) from exc
            finally:
                os.close(child_fd)
        else:
            try:
                os.unlink(name, dir_fd=directory_fd)
            except OSError as exc:
                raise translate_workspace_delete_error(exc, path) from exc


def translate_workspace_delete_error(exc: OSError, path: str, *, directory: bool = False) -> HTTPException:
    if exc.errno in {errno.ENOTEMPTY, errno.EEXIST}:
        return workspace_http_error(
            409,
            "workspace_directory_not_empty",
            f"Workspace directory is not empty: {path}",
        )
    if exc.errno in {errno.EBUSY, errno.EXDEV}:
        return workspace_http_error(
            409,
            "workspace_cross_device_delete",
            f"Workspace entry is a mounted filesystem and cannot be deleted: {path}",
        )
    if exc.errno == errno.EROFS:
        return workspace_http_error(403, "workspace_permission_denied", f"Permission denied: {path}")
    return translate_workspace_os_error(exc, path, directory=directory)


def remove_workspace_entry_sync(
    session_id: str,
    relative_path: str,
    expected_revision: str,
    recursive: bool,
) -> dict[str, Any]:
    _, root = session_workspace_root(session_id, for_write=True)
    normalized = normalize_workspace_path(relative_path)
    with workspace_write_lock(root, normalized):
        parent_fd, name = open_workspace_parent_fd(root, normalized)
        try:
            try:
                item_stat = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except OSError as exc:
                if exc.errno == errno.ENOENT:
                    raise workspace_http_error(
                        404,
                        "workspace_entry_not_found",
                        f"Workspace entry not found: {normalized}",
                    ) from exc
                raise translate_workspace_os_error(exc, normalized) from exc
            kind = workspace_entry_kind(item_stat, normalized)
            validate_workspace_entry_revision(expected_revision, item_stat, normalized)
            root_fd = open_workspace_directory_fd(root)
            try:
                root_device = os.fstat(root_fd).st_dev
            finally:
                os.close(root_fd)
            ensure_workspace_device(item_stat, root_device, normalized)
            if kind == "directory":
                if recursive:
                    directory_fd, directory_stat = open_workspace_delete_directory(
                        parent_fd,
                        name,
                        normalized,
                        root_device,
                    )
                    try:
                        if directory_stat.st_ino != item_stat.st_ino or directory_stat.st_dev != item_stat.st_dev:
                            raise workspace_http_error(
                                409,
                                "workspace_entry_conflict",
                                f"{normalized} changed while it was being deleted.",
                            )
                        validate_workspace_delete_tree(directory_fd, normalized, root_device)
                        remove_workspace_tree_contents(directory_fd, normalized, root_device)
                        latest_stat = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
                        if latest_stat.st_ino != directory_stat.st_ino or latest_stat.st_dev != directory_stat.st_dev:
                            raise workspace_http_error(
                                409,
                                "workspace_entry_conflict",
                                f"{normalized} changed while it was being deleted.",
                            )
                        try:
                            os.rmdir(name, dir_fd=parent_fd)
                        except OSError as exc:
                            raise translate_workspace_delete_error(exc, normalized, directory=True) from exc
                    finally:
                        os.close(directory_fd)
                else:
                    try:
                        os.rmdir(name, dir_fd=parent_fd)
                    except OSError as exc:
                        raise translate_workspace_delete_error(exc, normalized, directory=True) from exc
            else:
                try:
                    os.unlink(name, dir_fd=parent_fd)
                except OSError as exc:
                    raise translate_workspace_delete_error(exc, normalized) from exc
            fsync_workspace_directory(parent_fd, normalized)
            return {
                "root": str(root),
                "path": normalized,
                "kind": kind,
                "removed": True,
            }
        finally:
            os.close(parent_fd)


def workspace_search_rank(path: str, query: str) -> tuple[int, int, str]:
    lower = path.casefold()
    name = path.rsplit("/", 1)[-1].casefold()
    if not query:
        return (0, len(path), lower)
    if name == query:
        score = 0
    elif name.startswith(query):
        score = 1
    elif f"/{query}" in lower:
        score = 2
    elif query in name:
        score = 3
    else:
        score = 4
    return (score, len(path), lower)


def search_git_workspace_files(
    sess: dict[str, Any],
    root: Path,
    query: str,
    limit: int,
) -> dict[str, Any] | None:
    escaped_query = glob.escape(query.replace("\\", "/"))
    pathspecs = [
        f":(icase,glob)*{escaped_query}*",
        f":(icase,glob)**/*{escaped_query}*",
    ]
    try:
        with tempfile.TemporaryFile() as output:
            listed = subprocess.run(
                [
                    "git",
                    "-c",
                    "core.fsmonitor=false",
                    "-C",
                    str(root),
                    "ls-files",
                    "--cached",
                    "--others",
                    "--exclude-standard",
                    "-z",
                    "--",
                    *pathspecs,
                ],
                stdout=output,
                stderr=subprocess.DEVNULL,
                check=False,
                timeout=3,
                env={
                    **os.environ,
                    "GIT_OPTIONAL_LOCKS": "0",
                    "GIT_TERMINAL_PROMPT": "0",
                },
            )
            output_size = output.tell()
            output.seek(0)
            raw_paths = output.read(max(1024, MAX_WORKSPACE_GIT_SEARCH_BYTES))
    except (OSError, subprocess.SubprocessError):
        return None
    if listed.returncode != 0:
        return None
    output_truncated = output_size > len(raw_paths)
    if output_truncated and raw_paths and not raw_paths.endswith(b"\0"):
        raw_paths = raw_paths.rsplit(b"\0", 1)[0] + b"\0"

    clean_query = query.casefold()
    results: list[dict[str, Any]] = []
    scanned = 0
    seen: set[str] = set()
    scan_truncated = False
    for encoded_path in raw_paths.split(b"\0"):
        if not encoded_path:
            continue
        if scanned >= MAX_WORKSPACE_SEARCH_SCAN:
            scan_truncated = True
            break
        try:
            path = normalize_workspace_path(encoded_path.decode("utf-8"))
        except (UnicodeDecodeError, HTTPException):
            continue
        if path in seen:
            continue
        seen.add(path)
        scanned += 1
        if clean_query not in path.casefold():
            continue
        parent_fd = -1
        try:
            parent_fd, name = open_workspace_parent_fd(root, path)
            item_stat = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except (HTTPException, OSError):
            continue
        finally:
            if parent_fd >= 0:
                os.close(parent_fd)
        if not stat.S_ISREG(item_stat.st_mode):
            continue
        record = workspace_entry(path.rsplit("/", 1)[0] if "/" in path else "", name, item_stat)
        if not record:
            continue
        record["writable"] = not bool(sess.get("archived")) and bool(item_stat.st_mode & 0o222)
        results.append(record)

    results.sort(key=lambda item: workspace_search_rank(str(item["path"]), clean_query))
    return {
        "root": str(root),
        "query": query,
        "entries": results[:limit],
        "scanned": scanned,
        "truncated": output_truncated or scan_truncated or len(results) > limit,
        "limit": limit,
    }


def search_workspace_files_sync(session_id: str, query: str, limit: int) -> dict[str, Any]:
    sess, root = session_workspace_root(session_id)
    clean_query = str(query or "").strip().casefold()
    if clean_query:
        indexed = search_git_workspace_files(sess, root, clean_query, limit)
        if indexed is not None:
            indexed["query"] = str(query or "")
            return indexed
    queue: deque[str] = deque([""])
    results: list[dict[str, Any]] = []
    scanned = 0
    truncated = False
    deadline = time.monotonic() + MAX_WORKSPACE_SEARCH_SECONDS
    while queue:
        if time.monotonic() >= deadline:
            truncated = True
            break
        directory = queue.popleft()
        try:
            directory_fd = open_workspace_directory_fd(root, directory)
        except HTTPException:
            if not directory:
                raise
            continue
        try:
            names = sorted(os.listdir(directory_fd), key=lambda value: (value.casefold(), value))
            for name in names:
                try:
                    item_stat = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
                except OSError:
                    continue
                scanned += 1
                if scanned > MAX_WORKSPACE_SEARCH_SCAN:
                    truncated = True
                    queue.clear()
                    break
                if scanned % 128 == 0 and time.monotonic() >= deadline:
                    truncated = True
                    queue.clear()
                    break
                path = f"{directory}/{name}" if directory else name
                if stat.S_ISDIR(item_stat.st_mode):
                    if name not in WORKSPACE_SEARCH_IGNORED_DIRECTORIES and not stat.S_ISLNK(item_stat.st_mode):
                        queue.append(path)
                    continue
                if not stat.S_ISREG(item_stat.st_mode):
                    continue
                if clean_query and clean_query not in path.casefold():
                    continue
                results.append({
                    "name": name,
                    "path": path,
                    "kind": "file",
                    "size": int(item_stat.st_size),
                    "mtime_ns": int(item_stat.st_mtime_ns),
                    "hidden": name.startswith("."),
                    "writable": not bool(sess.get("archived")) and bool(item_stat.st_mode & 0o222),
                    "revision": workspace_entry_revision(item_stat),
                })
                if not clean_query and len(results) > limit:
                    truncated = True
                    queue.clear()
                    break
        finally:
            os.close(directory_fd)
    results.sort(key=lambda item: workspace_search_rank(str(item["path"]), clean_query))
    return {
        "root": str(root),
        "query": str(query or ""),
        "entries": results[:limit],
        "scanned": min(scanned, MAX_WORKSPACE_SEARCH_SCAN),
        "truncated": truncated or len(results) > limit,
        "limit": limit,
    }


def server_identity() -> str:
    machine = ""
    for path in (Path("/etc/machine-id"), Path("/var/lib/dbus/machine-id")):
        with suppress(Exception):
            machine = path.read_text(encoding="utf-8").strip()
            if machine:
                break
    if not machine:
        machine = os.uname().nodename
    payload = f"{machine}|{STATE_DIR.resolve()}".encode("utf-8", errors="ignore")
    return hashlib.sha256(payload).hexdigest()[:24]


def ensure_dirs(session_id: str | None = None) -> None:
    STATE_DIR.mkdir(parents=True, exist_ok=True)
    FILES_ROOT.mkdir(parents=True, exist_ok=True)
    CODE_DIFFS_ROOT.mkdir(parents=True, exist_ok=True)
    CROSS_CHAT_AUTHORITY_ROOT.mkdir(parents=True, exist_ok=True, mode=0o700)
    if session_id:
        session_dir(session_id).mkdir(parents=True, exist_ok=True)
        uploads_dir(session_id).mkdir(parents=True, exist_ok=True)
        manifests_dir(session_id).mkdir(parents=True, exist_ok=True)
        artifact_publications_dir(session_id).mkdir(parents=True, exist_ok=True)
        code_diffs_dir(session_id).mkdir(parents=True, exist_ok=True)


def _git_command(
    repo_root: str,
    args: list[str],
    *,
    env: dict[str, str] | None = None,
    stdout: Any = subprocess.PIPE,
) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        ["git", "-c", "core.quotePath=false", "-C", repo_root, *args],
        stdin=subprocess.DEVNULL,
        stdout=stdout,
        stderr=subprocess.PIPE,
        text=True,
        env=env,
        timeout=CODE_DIFF_SNAPSHOT_TIMEOUT_SECONDS,
        check=False,
    )


def _capture_git_tree(session_id: str, run_id: str, cwd: str) -> dict[str, str] | None:
    """Snapshot the worktree through a temporary index without touching the real index."""
    try:
        probe = subprocess.run(
            ["git", "-C", cwd, "rev-parse", "--show-toplevel"],
            stdin=subprocess.DEVNULL,
            capture_output=True,
            text=True,
            timeout=15,
            check=False,
        )
    except (OSError, subprocess.SubprocessError):
        return None
    repo_root = probe.stdout.strip()
    if probe.returncode != 0 or not repo_root:
        return None

    ensure_dirs(session_id)
    index_path = code_diffs_dir(session_id) / f".{safe_name(run_id)}-{uuid.uuid4().hex}.index"
    env = dict(os.environ)
    env["GIT_INDEX_FILE"] = str(index_path)
    try:
        seeded_from_index = False
        index_probe = _git_command(repo_root, ["rev-parse", "--git-path", "index"])
        source_index = Path(index_probe.stdout.strip()) if index_probe.returncode == 0 else Path()
        if source_index and not source_index.is_absolute():
            source_index = Path(repo_root) / source_index
        if source_index.is_file():
            shutil.copy2(source_index, index_path)
            seeded_from_index = True
        else:
            head = _git_command(repo_root, ["rev-parse", "--verify", "HEAD"])
            read_args = ["read-tree", head.stdout.strip()] if head.returncode == 0 and head.stdout.strip() else ["read-tree", "--empty"]
            if _git_command(repo_root, read_args, env=env).returncode != 0:
                return None
        staged = _git_command(repo_root, ["add", "-A", "--", "."], env=env)
        if staged.returncode != 0 and seeded_from_index:
            with suppress(OSError):
                index_path.unlink()
            head = _git_command(repo_root, ["rev-parse", "--verify", "HEAD"])
            read_args = ["read-tree", head.stdout.strip()] if head.returncode == 0 and head.stdout.strip() else ["read-tree", "--empty"]
            if _git_command(repo_root, read_args, env=env).returncode == 0:
                staged = _git_command(repo_root, ["add", "-A", "--", "."], env=env)
        if staged.returncode != 0:
            logger.info(
                "code diff snapshot skipped session=%s run=%s: %s",
                session_id,
                run_id,
                staged.stderr.strip()[:500],
            )
            return None
        tree = _git_command(repo_root, ["write-tree"], env=env)
        tree_id = tree.stdout.strip()
        if tree.returncode != 0 or not tree_id:
            return None
        return {"repo_root": repo_root, "tree": tree_id}
    except (OSError, subprocess.SubprocessError) as exc:
        logger.info("code diff snapshot failed session=%s run=%s error=%s", session_id, run_id, exc)
        return None
    finally:
        with suppress(OSError):
            index_path.unlink()
        with suppress(OSError):
            Path(f"{index_path}.lock").unlink()


def _parse_git_numstat(source: str) -> list[dict[str, Any]]:
    files: list[dict[str, Any]] = []
    for raw_line in source.splitlines():
        parts = raw_line.split("\t", 2)
        if len(parts) != 3:
            continue
        added_raw, deleted_raw, path = parts
        added = int(added_raw) if added_raw.isdigit() else None
        deleted = int(deleted_raw) if deleted_raw.isdigit() else None
        files.append({
            "path": path.strip(),
            "additions": added,
            "deletions": deleted,
            "binary": added is None or deleted is None,
        })
    return files


def _patch_changed_paths(source: str) -> set[str]:
    paths: set[str] = set()
    # Codex's orchestration tool embeds apply_patch in a JavaScript string, so
    # patch newlines arrive as literal `\\n` sequences rather than line breaks.
    expanded = str(source or "").replace("\\r\\n", "\n").replace("\\n", "\n")
    for raw_line in expanded.splitlines():
        line = raw_line.strip()
        match = re.match(r"^\*\*\* (?:Add|Update|Delete) File:\s*(.+?)\s*$", line)
        if match:
            paths.add(match.group(1).rstrip("\\").strip())
            continue
        match = re.match(r"^\*\*\* Move to:\s*(.+?)\s*$", line)
        if match:
            paths.add(match.group(1).rstrip("\\").strip())
            continue
        match = re.match(r"^(?:---|\+\+\+)\s+(?:[ab]/)?(.+?)\s*$", line)
        if match and match.group(1) != "/dev/null":
            paths.add(match.group(1).rstrip("\\").strip())
    return paths


def tool_changed_paths(tool: dict[str, Any]) -> set[str]:
    """Return only paths explicitly owned by a mutating provider tool call."""
    name = str(tool.get("name") or "").strip().lower().replace("-", "_")
    tool_input = tool.get("input") if isinstance(tool.get("input"), dict) else {}
    paths: set[str] = set()
    direct_path_tools = {
        "edit", "write", "multiedit", "multi_edit", "notebookedit", "notebook_edit",
        "str_replace_editor", "create_file", "delete_file",
    }
    if name in direct_path_tools:
        for key in ("file_path", "path", "notebook_path"):
            value = tool_input.get(key)
            if isinstance(value, str) and value.strip():
                paths.add(value.strip())
    if name in {"apply_patch", "applypatch", "patch"}:
        patch = tool_input.get("patch") or tool_input.get("input") or tool_input.get("value")
        if isinstance(patch, str):
            paths.update(_patch_changed_paths(patch))
    elif name in {"exec", "run_javascript", "javascript"}:
        for key in ("value", "code", "script", "input"):
            source = tool_input.get(key)
            if isinstance(source, str) and "apply_patch" in source and "***" in source:
                paths.update(_patch_changed_paths(source))
    return paths


def _normalize_changed_paths(paths: set[str], repo_root: str, cwd: str) -> list[str]:
    root = Path(repo_root).expanduser().resolve()
    working = Path(cwd).expanduser().resolve()
    normalized: set[str] = set()
    for raw in paths:
        clean = str(raw or "").strip().strip("\"'`")
        if not clean or clean == "/dev/null":
            continue
        if clean.startswith("a/") or clean.startswith("b/"):
            clean = clean[2:]
        candidate = Path(clean).expanduser()
        candidates = [candidate] if candidate.is_absolute() else [working / candidate, root / candidate]
        for resolved in candidates:
            try:
                relative = resolved.resolve().relative_to(root)
            except (OSError, ValueError):
                continue
            if relative.parts and ".." not in relative.parts:
                normalized.add(relative.as_posix())
                break
    return sorted(normalized)


def _write_turn_code_diff(
    session_id: str,
    run_id: str,
    backend: str,
    baseline: dict[str, str],
    cwd: str,
    changed_paths: set[str],
) -> dict[str, Any] | None:
    current = _capture_git_tree(session_id, run_id, cwd)
    if not current or current.get("repo_root") != baseline.get("repo_root"):
        return None
    base_tree = str(baseline.get("tree") or "")
    current_tree = str(current.get("tree") or "")
    if not base_tree or not current_tree or base_tree == current_tree:
        return None

    repo_root = str(current["repo_root"])
    attributed_paths = _normalize_changed_paths(changed_paths, repo_root, cwd)
    if not attributed_paths:
        logger.info(
            "code diff skipped session=%s run=%s: no agent-owned edit paths",
            session_id,
            run_id,
        )
        return None
    diff_root = code_diffs_dir(session_id)
    patch_path = diff_root / f"{safe_name(run_id)}.patch"
    patch_tmp = diff_root / f".{safe_name(run_id)}-{uuid.uuid4().hex}.patch"
    try:
        with patch_tmp.open("w", encoding="utf-8") as output:
            patch = _git_command(
                repo_root,
                ["diff", "--no-ext-diff", "--no-textconv", "--find-renames", "--unified=3", base_tree, current_tree, "--", *attributed_paths],
                stdout=output,
            )
        if patch.returncode != 0 or patch_tmp.stat().st_size == 0:
            with suppress(OSError):
                patch_tmp.unlink()
            return None
        patch_tmp.replace(patch_path)
        numstat = _git_command(repo_root, ["diff", "--numstat", "--find-renames", base_tree, current_tree, "--", *attributed_paths])
        files = _parse_git_numstat(numstat.stdout if numstat.returncode == 0 else "")
        additions = sum(int(item["additions"] or 0) for item in files)
        deletions = sum(int(item["deletions"] or 0) for item in files)
        metadata = {
            "run_id": run_id,
            "backend": backend,
            "repository_root": repo_root,
            "diff_files": files,
            "files_changed": len(files),
            "additions": additions,
            "deletions": deletions,
            "byte_count": patch_path.stat().st_size,
            "created_at": now_iso(),
            "attribution": "agent_tool_paths",
            "attributed_paths": attributed_paths,
        }
        metadata_path = diff_root / f"{safe_name(run_id)}.json"
        metadata_tmp = diff_root / f".{safe_name(run_id)}-{uuid.uuid4().hex}.json"
        metadata_tmp.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
        metadata_tmp.replace(metadata_path)
        return metadata
    except (OSError, subprocess.SubprocessError) as exc:
        logger.warning("code diff capture failed session=%s run=%s error=%s", session_id, run_id, exc)
        with suppress(OSError):
            patch_tmp.unlink()
        return None


async def capture_git_baseline(session_id: str, run_id: str, cwd: str) -> dict[str, str] | None:
    return await asyncio.to_thread(_capture_git_tree, session_id, run_id, cwd)


async def publish_turn_code_diff(
    session_id: str,
    run_id: str,
    backend: str,
    cwd: str,
    baseline: dict[str, str] | None,
    changed_paths: set[str],
) -> None:
    if not baseline:
        return
    metadata = await asyncio.to_thread(_write_turn_code_diff, session_id, run_id, backend, baseline, cwd, changed_paths)
    if metadata:
        await append_event(session_id, "code_diff", metadata)


EVENT_SEQ_CACHE: dict[str, int] = {}
EVENT_SEQ_LOCK = asyncio.Lock()
EVENT_DELIVERY_LOCKS: dict[str, asyncio.Lock] = {}
ARTIFACT_PUBLICATION_LOCK_STRIPES = tuple(asyncio.Lock() for _ in range(64))
TIMELINE_INDEX_CACHE_MAX = int(agentsdock_setting("TIMELINE_INDEX_CACHE_MAX", "24"))
TIMELINE_INDEX_CACHE: OrderedDict[str, dict[str, Any]] = OrderedDict()
# Retained as a compatibility/testing surface; synchronization uses the fixed
# stripe pool below so deleted-session churn cannot leak one lock per chat.
TIMELINE_INDEX_LOCKS: dict[str, threading.Lock] = {}
# Cache membership and the per-session lock registry are shared across every
# request worker.  Protect them independently from the per-session scan locks:
# an LRU eviction for chat A must never remove or recreate chat B's lock while
# chat B is building/reading its index.
TIMELINE_INDEX_CACHE_LOCK = threading.RLock()
TIMELINE_INDEX_LOCK_STRIPES = tuple(threading.Lock() for _ in range(64))
FORK_INTERNAL_RUN_CACHE_MAX = int(agentsdock_setting("FORK_INTERNAL_RUN_CACHE_MAX", "128"))
FORK_INTERNAL_RUN_CACHE: OrderedDict[str, dict[str, Any]] = OrderedDict()
FORK_INTERNAL_RUN_LOCKS: dict[str, threading.Lock] = {}
HISTORY_SEARCH_DB = STATE_DIR / "history_search.sqlite3"
HISTORY_SEARCH_LOCK = threading.Lock()
HISTORY_SEARCH_INDEX_VERSION = "3"
HISTORY_SEARCH_DIRTY: set[str] = set()
HISTORY_SEARCH_SYNC_INTERVAL_SECONDS = max(
    0.25, float(agentsdock_setting("HISTORY_SEARCH_SYNC_INTERVAL_SECONDS", "1.0"))
)
HISTORY_SEARCH_INITIAL_DELAY_SECONDS = max(
    0.0, float(agentsdock_setting("HISTORY_SEARCH_INITIAL_DELAY_SECONDS", "30.0"))
)
HISTORY_SEARCH_FULL_SYNC_INTERVAL_SECONDS = max(
    30.0, float(agentsdock_setting("HISTORY_SEARCH_FULL_SYNC_INTERVAL_SECONDS", "300"))
)


def last_event_seq_from_file(path: Path) -> int:
    """Read the last JSONL event seq without scanning huge chat histories."""
    if not path.exists():
        return 0
    try:
        with path.open("rb") as f:
            f.seek(0, os.SEEK_END)
            size = f.tell()
            if size <= 0:
                return 0
            buffer = b""
            pos = size
            read_total = 0
            max_backscan = min(size, 16 * 1024 * 1024)
            while pos > 0 and read_total < max_backscan:
                chunk_size = min(pos, 256 * 1024, max_backscan - read_total)
                pos -= chunk_size
                f.seek(pos)
                buffer = f.read(chunk_size) + buffer
                read_total += chunk_size
                lines = buffer.splitlines()
                if pos > 0 and buffer and not buffer.startswith(b"\n"):
                    lines = lines[1:]
                for raw_line in reversed(lines):
                    if not raw_line.strip():
                        continue
                    with suppress(Exception):
                        event = json.loads(raw_line.decode("utf-8", "replace"))
                        return int(event.get("seq") or 0)
    except Exception as exc:
        logger.warning("failed to read last event seq for %s: %s", path, exc)
    return 0


async def next_event_seq(session_id: str, path: Path) -> int:
    async with EVENT_SEQ_LOCK:
        seq = EVENT_SEQ_CACHE.get(session_id)
        if seq is None:
            seq = await asyncio.to_thread(last_event_seq_from_file, path)
        seq += 1
        EVENT_SEQ_CACHE[session_id] = seq
        return seq


def event_delivery_lock(session_id: str) -> asyncio.Lock:
    """Serialize persisted and live event delivery within one chat."""
    return EVENT_DELIVERY_LOCKS.setdefault(session_id, asyncio.Lock())


def artifact_publication_lock(
    session_id: str,
    publication_id: str,
) -> asyncio.Lock:
    digest = hashlib.sha256(
        f"{session_id}\0{publication_id}".encode("utf-8")
    ).digest()
    return ARTIFACT_PUBLICATION_LOCK_STRIPES[
        int.from_bytes(digest[:2], "big") % len(ARTIFACT_PUBLICATION_LOCK_STRIPES)
    ]


async def forget_event_seq(session_id: str) -> None:
    async with EVENT_SEQ_LOCK:
        EVENT_SEQ_CACHE.pop(session_id, None)
    EVENT_DELIVERY_LOCKS.pop(session_id, None)
    timeline_lock = timeline_index_session_lock(session_id)
    with timeline_lock:
        with TIMELINE_INDEX_CACHE_LOCK:
            TIMELINE_INDEX_CACHE.pop(session_id, None)
    FORK_INTERNAL_RUN_CACHE.pop(session_id, None)
    FORK_INTERNAL_RUN_LOCKS.pop(session_id, None)


def token_matches(candidate: str | None) -> bool:
    if not AGENT_TOKEN:
        return True
    if not candidate:
        return False
    return hmac.compare_digest(candidate, AGENT_TOKEN)


def bearer_token(authorization: str | None) -> str | None:
    if not authorization:
        return None
    scheme, _, value = authorization.partition(" ")
    if scheme.lower() == "bearer" and value:
        return value.strip()
    return None


def request_authorized(request: Request) -> bool:
    if not AGENT_TOKEN:
        return True
    return (
        token_matches(bearer_token(request.headers.get("authorization")))
        or token_matches(request.headers.get("x-agentsdock-token"))
        or token_matches(request.headers.get("x-zenithdock-token"))
        or token_matches(request.query_params.get("token"))
    )


def network_host_is_loopback(host: str) -> bool:
    try:
        address = ipaddress.ip_address(host)
    except ValueError:
        return host.lower() == "localhost"
    if isinstance(address, ipaddress.IPv6Address) and address.ipv4_mapped:
        address = address.ipv4_mapped
    return address.is_loopback


def request_client_is_loopback(request: Request) -> bool:
    # Deliberately ignore Forwarded/X-Forwarded-For. This privileged endpoint
    # is for an agent process talking directly to its own AgentsServer only.
    client = request.client
    return bool(client and network_host_is_loopback(str(client.host or "")))


def websocket_authorized(ws: WebSocket) -> bool:
    if not AGENT_TOKEN:
        return True
    return (
        token_matches(bearer_token(ws.headers.get("authorization")))
        or token_matches(ws.headers.get("x-agentsdock-token"))
        or token_matches(ws.headers.get("x-zenithdock-token"))
        or token_matches(ws.query_params.get("token"))
    )


class CreateSessionRequest(BaseModel):
    title: str | None = None
    folder: str | None = None
    cwd: str | None = None
    backend: str | None = None
    model: str | None = None
    effort: str | None = None
    system_prompt: str | None = Field(default=None, max_length=MAX_SESSION_SYSTEM_PROMPT_CHARS)
    pinned: bool | None = None
    archived: bool | None = None
    provider_session_id: str | None = None
    session_id: str | None = None
    claude_session_id: str | None = None
