@app.get("/api/sessions/{session_id}")
async def get_session(
    session_id: str,
    after: int = 0,
    before: int | None = None,
    limit: int = DEFAULT_SESSION_EVENT_LIMIT,
    tail: bool = True,
    visible: bool = False,
    compact: bool = False,
    page_mode: str | None = None,
    semantic_before: int | None = None,
) -> dict[str, Any]:
    ensure_session_not_initializing(session_id)
    sess = STORE.sessions.get(session_id)
    if not sess:
        raise HTTPException(status_code=404, detail="session not found")
    normalized_page_mode = str(page_mode or "").strip().lower()
    if normalized_page_mode not in {"", "semantic"}:
        raise HTTPException(status_code=400, detail="page_mode must be semantic")
    page_tail = tail and after <= 0
    semantic_page: dict[str, Any] | None = None
    if normalized_page_mode == "semantic":
        semantic_page = await asyncio.to_thread(
            read_semantic_timeline_page,
            session_id,
            after=after,
            semantic_before=semantic_before if semantic_before is not None else before,
            limit=limit,
            tail=page_tail,
        )
        events = semantic_page["events"]
        latest_seq = int(semantic_page["latest_seq"])
        event_count = int(semantic_page["semantic_total"])
        omitted_before = int(semantic_page["semantic_omitted_before"])
        omitted_after = int(semantic_page["semantic_omitted_after"])
    elif visible or compact:
        if after > 0 and before is None and not page_tail:
            events, latest_seq, event_count, omitted_before, omitted_after = await asyncio.to_thread(
                read_visible_events_after_page,
                session_id,
                after=after,
                limit=limit,
                compact=compact,
            )
        else:
            events, latest_seq, event_count, omitted_before, omitted_after = await asyncio.to_thread(
                read_visible_events_page,
                session_id,
                after=after,
                before=before,
                limit=limit,
                tail=page_tail,
                compact=compact,
            )
    elif after > 0 and before is None:
        events = read_events(session_id, after=after, before=before, limit=limit, tail=page_tail)
        _, latest_seq, event_count = event_seq_bounds(session_id)
        omitted_before = 0
        if events:
            omitted_after = max(0, latest_seq - int(events[-1].get("seq", 0)))
        else:
            omitted_after = max(0, latest_seq - after)
    else:
        events = read_events(session_id, after=after, before=before, limit=limit, tail=page_tail)
        latest_seq = int(events[-1].get("seq", 0)) if events else 0
        event_count = 0
        omitted_before = max(0, int(events[0].get("seq", 1)) - 1) if page_tail and events else 0
        if events:
            omitted_after = max(0, latest_seq - int(events[-1].get("seq", 0)))
        elif after > 0:
            omitted_after = max(0, latest_seq - after)
        else:
            omitted_after = 0
    response = {
        "session": public_session(sess),
        "events": events,
        "queued_turns": await queued_turns_snapshot(session_id),
        "events_omitted_before": omitted_before,
        "events_omitted_after": omitted_after,
        "latest_seq": latest_seq,
        "event_count": event_count,
    }
    if semantic_page is not None:
        response.update({
            "semantic_item_count": semantic_page["semantic_item_count"],
            "semantic_total": semantic_page["semantic_total"],
            "semantic_omitted_before": semantic_page["semantic_omitted_before"],
            "semantic_omitted_after": semantic_page["semantic_omitted_after"],
            "next_semantic_before": semantic_page["next_semantic_before"],
        })
    return response


@app.post("/api/sessions/{session_id}/import-history")
async def import_history(session_id: str, req: ImportHistoryRequest) -> dict[str, Any]:
    sess = STORE.sessions.get(session_id)
    if not sess:
        raise HTTPException(status_code=404, detail="session not found")
    result = await import_session_history(sess, force=req.force, limit=req.limit)
    return {"ok": True, **result}


@app.post("/api/sessions/{session_id}/digest")
async def create_handoff_digest(session_id: str, req: HandoffDigestRequest) -> dict[str, Any]:
    return await build_handoff_digest(
        session_id,
        detail=req.detail,
        user_prompt=req.user_prompt,
        target_session_id=req.target_session_id,
        summarizer_backend=req.summarizer_backend,
        summarizer_model=req.summarizer_model,
        summarizer_effort=req.summarizer_effort,
    )


@app.post("/api/sessions/{session_id}/digest/send")
async def send_handoff_digest_background(session_id: str, req: HandoffDigestSendRequest) -> dict[str, Any]:
    source = STORE.sessions.get(session_id)
    if not source:
        raise HTTPException(status_code=404, detail="source session not found")
    target = STORE.sessions.get(req.target_session_id)
    if not target:
        raise HTTPException(status_code=404, detail="target session not found")
    if session_id == req.target_session_id:
        raise HTTPException(status_code=400, detail="target chat must be different from source chat")
    digest_job_id = f"digest_{uuid.uuid4().hex[:16]}"
    await create_handoff_digest_job(digest_job_id, session_id, req)
    started_event = await append_event(session_id, "handoff_digest_started", {
        "digest_job_id": digest_job_id,
        "source_session_id": session_id,
        "target_session_id": req.target_session_id,
        "message": f"Creating a context digest for {target.get('title') or req.target_session_id}.",
        "detail": req.detail,
        "user_prompt": req.user_prompt,
    })
    turn = await run_handoff_digest_send(digest_job_id, session_id, req)
    return {
        "ok": True,
        "digest_job_id": digest_job_id,
        "queued": bool(turn.get("queued")),
        "queued_id": turn.get("queued_id"),
        "run_id": turn.get("run_id"),
        "event": started_event,
        "session": public_session(STORE.sessions[session_id]),
    }


async def ensure_claude_permission_mode_update_allowed(
    session_id: str,
    current: dict[str, Any],
    patch: dict[str, Any],
) -> None:
    """Fence process policy changes without rejecting an idempotent save."""

    if "claude_permission_mode" not in patch:
        return
    requested = effective_claude_permission_mode({
        "claude_permission_mode": patch.get("claude_permission_mode"),
    })
    if requested == effective_claude_permission_mode(current):
        return
    async with ACTIVE_LOCK:
        if session_id in BUSY_SESSIONS or ACTIVE.get(session_id) is not None:
            raise HTTPException(
                status_code=409,
                detail=(
                    "wait for or stop the active Claude turn before changing "
                    "its permission mode"
                ),
            )


async def ensure_backend_update_allowed(
    session_id: str,
    current: dict[str, Any],
    patch: dict[str, Any],
) -> None:
    """Fence real backend changes while provider work owns the session.

    ``start_turn`` registers its request task before it acquires the session
    lifecycle lock or reserves ``BUSY_SESSIONS``.  Checking the task registry
    closes that launch race, including a first turn with no provider identity
    yet, while still allowing idempotent saves from older clients.
    """

    if "backend" not in patch or patch.get("backend") is None:
        return
    current_backend = str(
        current.get("backend") or DEFAULT_BACKEND
    ).strip().lower()
    requested_backend = str(
        patch.get("backend") or DEFAULT_BACKEND
    ).strip().lower()
    if requested_backend == current_backend:
        return

    async with ACTIVE_LOCK:
        provider_starting = any(
            not task.done()
            for task in tuple(SESSION_TURN_TASKS.get(session_id) or ())
        )
        if (
            session_id in BUSY_SESSIONS
            or ACTIVE.get(session_id) is not None
            or provider_starting
        ):
            raise HTTPException(
                status_code=409,
                detail=(
                    "wait for or stop the active turn before changing its "
                    "backend"
                ),
            )


@app.patch("/api/sessions/{session_id}")
async def update_session(session_id: str, req: UpdateSessionRequest) -> dict[str, Any]:
    ensure_session_not_initializing(session_id)
    patch = req.model_dump(exclude_unset=True)
    if SESSION_LIFECYCLE_UPDATE_FIELDS.intersection(patch):
        async with session_lifecycle_lock(session_id):
            current = STORE.sessions.get(session_id)
            if not current:
                raise HTTPException(status_code=404, detail="session not found")
            # Validate the complete model/effort pair atomically. App-server
            # applies the saved selection through the next turn/start; it does
            # not currently expose a client RPC for mutating a loaded thread.
            preview_session_runtime_update(current, patch)
            await ensure_backend_update_allowed(
                session_id,
                current,
                patch,
            )
            await ensure_claude_permission_mode_update_allowed(
                session_id,
                current,
                patch,
            )
            sess = await STORE.update(session_id, patch)
    else:
        # Title, folder, pin, and archive edits must remain lightweight. They
        # do not interact with provider runtime state and should not queue
        # behind a long Codex lifecycle operation.
        sess = await STORE.update(session_id, patch)
    if req.archived is True:
        try:
            await terminalize_archived_cross_chat_session(session_id)
        except Exception as exc:
            # Archiving is durable. The terminal lifecycle outbox/restart
            # reconciliation will retry any handoff cleanup that did not
            # finish in this request.
            logger.warning(
                "could not terminalize cross-chat queue for archived session %s: %s",
                session_id,
                concise_error_message(exc),
            )
        try:
            await asyncio.to_thread(kill_terminal_session, session_id)
        except Exception as exc:
            # Archiving is already durable at this point. Terminal cleanup is
            # best-effort and must not turn a successful archive into a 500.
            logger.warning("could not clean up terminal for archived session %s: %s", session_id, exc)
    return {"session": public_session(sess)}


async def codex_runtime_snapshot(session_id: str) -> dict[str, Any]:
    session = STORE.sessions.get(session_id)
    if not session:
        raise HTTPException(status_code=404, detail="session not found")
    is_codex = str(session.get("backend") or DEFAULT_BACKEND) == BACKEND_CODEX
    available = is_codex and CODEX_TRANSPORT != CODEX_TRANSPORT_EXEC
    thread_id = str(session_provider_id(session) or "")
    manager = CODEX_APP_SERVER_MANAGER
    thread_loaded = bool(
        thread_id and manager is not None and manager.is_thread_loaded(thread_id)
    )
    async with CODEX_PENDING_INTERACTIONS_LOCK:
        pending = [
            public_codex_interaction(item)
            for item in CODEX_PENDING_INTERACTIONS.values()
            if item.get("session_id") == session_id
            and not item.get("responded")
        ]
    cached_status = session.get("codex_thread_status")
    async with ACTIVE_LOCK:
        active = session_id in BUSY_SESSIONS
    if active:
        status = (
            cached_status
            if isinstance(cached_status, dict)
            and cached_status.get("type") == "active"
            else {"type": "active", "activeFlags": []}
        )
    elif thread_loaded:
        status = (
            cached_status
            if isinstance(cached_status, dict)
            and cached_status.get("type") == "systemError"
            else {"type": "idle"}
        )
    else:
        status = {"type": "notLoaded"}
    permission_cache_key = existing_cwd(
        str(session.get("cwd") or DEFAULT_CWD)
    )
    permission_profiles = cached_codex_permission_profiles(
        permission_cache_key,
        manager,
    ) or []
    return {
        "available": available,
        "transport": CODEX_TRANSPORT,
        "goals_enabled": CODEX_GOALS_ENABLED,
        "interactive_capability": CODEX_INTERACTIVE_CLIENT_CAPABILITY,
        "persisted_thread": bool(thread_id),
        "thread_loaded": thread_loaded,
        "status": status,
        "goal": session.get("codex_goal"),
        "time_budget_seconds": session.get("codex_goal_time_budget_seconds"),
        "time_budget_exhausted": codex_goal_time_budget_is_exhausted(session),
        "token_usage": session.get("codex_token_usage"),
        "token_usage_snapshot": session.get("codex_token_usage_snapshot"),
        **context_usage_runtime_fields(session, backend=BACKEND_CODEX),
        "pending_interactions": pending,
        "permission_profiles": permission_profiles,
        "background_terminals_supported": CODEX_BACKGROUND_TERMINALS_SUPPORTED,
        "policy": {
            "approval_policy": (
                session.get("codex_approval_policy")
                if session.get("codex_approval_policy")
                in CODEX_APPROVAL_POLICIES
                else CODEX_DEFAULT_APPROVAL_POLICY
            ),
            "sandbox_mode": (
                session.get("codex_sandbox_mode")
                if session.get("codex_sandbox_mode") in CODEX_SANDBOX_MODES
                else CODEX_DEFAULT_SANDBOX_MODE
            ),
            "permission_profile": (
                str(
                    session.get("codex_permission_profile")
                    or CODEX_DEFAULT_PERMISSION_PROFILE
                    or ""
                ).strip()
                or CODEX_DEFAULT_PERMISSION_PROFILE
            ),
            "approvals_reviewer": (
                session.get("codex_approvals_reviewer")
                if session.get("codex_approvals_reviewer")
                in CODEX_APPROVAL_REVIEWERS
                else CODEX_DEFAULT_APPROVALS_REVIEWER
            ),
        },
    }


def session_registry_has_live_tasks(
    registry: dict[Any, Any],
    session_id: str,
) -> bool:
    """Return whether a task registry still owns work for one chat."""

    direct = registry.get(session_id)
    if isinstance(direct, (set, list, tuple)):
        return any(
            isinstance(task, asyncio.Task) and not task.done()
            for task in tuple(direct)
        )
    return any(
        isinstance(key, tuple)
        and key
        and str(key[0]) == session_id
        and isinstance(task, asyncio.Task)
        and not task.done()
        for key, task in tuple(registry.items())
    )


async def clear_stale_provider_interactions(
    session_id: str,
    backend: str,
) -> int:
    """Retire orphaned cards only after their live handler has disappeared."""

    if backend == BACKEND_CODEX:
        registry = CODEX_INTERACTION_HANDLER_TASKS
        pending_registry = CODEX_PENDING_INTERACTIONS
        pending_lock = CODEX_PENDING_INTERACTIONS_LOCK
        cancel = cancel_codex_interactions
        update_metadata = update_codex_pending_session_metadata
    else:
        registry = CLAUDE_INTERACTION_HANDLER_TASKS
        pending_registry = CLAUDE_PENDING_INTERACTIONS
        pending_lock = CLAUDE_PENDING_INTERACTIONS_LOCK
        cancel = cancel_claude_interactions
        update_metadata = update_claude_pending_session_metadata

    if session_registry_has_live_tasks(registry, session_id):
        raise HTTPException(
            status_code=409,
            detail=(
                f"Resolve or cancel the pending {backend.title()} approval "
                "or question before reloading the provider."
            ),
        )

    async with pending_lock:
        selected = [
            (interaction_id, pending)
            for interaction_id, pending in pending_registry.items()
            if pending.get("session_id") == session_id
        ]
        unresolved = [
            pending
            for _interaction_id, pending in selected
            if not pending.get("responded")
        ]

    # A pending Future without its registered request-handler task is an
    # orphan from an already-finished provider lifecycle. Settle it with the
    # existing least-privilege cancellation path before pruning the stale UI
    # record. Live handler tasks were rejected above and are never killed.
    if unresolved:
        await cancel(session_id, resolution="provider_reloaded")

    removed = 0
    async with pending_lock:
        for interaction_id, pending in tuple(pending_registry.items()):
            if pending.get("session_id") != session_id:
                continue
            # With no handler task left, every record for this chat is
            # process-orphaned, including malformed legacy rows without a
            # Future. It is safe to remove after the least-privilege settle.
            pending_registry.pop(interaction_id, None)
            removed += 1
    if selected:
        await update_metadata(session_id)
    return removed


def codex_session_has_live_subagents(session_id: str) -> bool:
    """Return whether this chat owns a child in the current app-server."""

    with CODEX_SUBAGENT_INDEX_LOCK:
        states = [
            (thread_id, dict(state))
            for thread_id, state in CODEX_SUBAGENT_STATE.items()
            if str(state.get("session_id") or "") == session_id
        ]
    return any(
        codex_subagent_has_live_owner(thread_id, state)
        for thread_id, state in states
    )


def claude_manager_owns_chat(
    manager: ClaudeSDKSupervisorManager,
    session_id: str,
) -> bool:
    """Include idle/disconnected supervisors that ``is_loaded`` omits."""

    snapshots = getattr(manager, "snapshots", None)
    if not callable(snapshots):
        return bool(manager.is_loaded(session_id))
    return any(
        str(getattr(snapshot, "chat_id", "")) == session_id
        and not bool(getattr(snapshot, "closed", False))
        for snapshot in snapshots()
    )


async def reload_session_provider(session_id: str) -> dict[str, Any]:
    """Unload only one idle provider context; its next turn resumes it.

    Provider identities and AgentsDock history remain untouched. This is an
    intentionally fail-closed lifecycle operation: it never interrupts a
    turn, prompt, child agent, or background terminal.
    """

    async with session_lifecycle_lock(session_id):
        ensure_session_not_deleting(session_id)
        session = STORE.sessions.get(session_id)
        if not session:
            raise HTTPException(status_code=404, detail="session not found")
        backend = str(
            session.get("backend") or DEFAULT_BACKEND
        ).strip().lower()
        if backend not in {BACKEND_CODEX, BACKEND_CLAUDE}:
            raise HTTPException(
                status_code=409,
                detail="Provider reload requires a Codex or Claude chat.",
            )
        if (
            backend == BACKEND_CODEX
            and CODEX_TRANSPORT == CODEX_TRANSPORT_EXEC
        ):
            raise HTTPException(
                status_code=503,
                detail="Codex provider reload requires the app-server transport.",
            )
        if (
            backend == BACKEND_CLAUDE
            and CLAUDE_TRANSPORT == CLAUDE_TRANSPORT_PRINT
        ):
            raise HTTPException(
                status_code=503,
                detail="Claude provider reload requires the Agent SDK transport.",
            )

        maintenance_reserved = False
        try:
            async with ACTIVE_LOCK:
                provider_starting = session_registry_has_live_tasks(
                    SESSION_TURN_TASKS,
                    session_id,
                )
                native_action_active = (
                    backend == BACKEND_CODEX
                    and session_registry_has_live_tasks(
                        CODEX_NATIVE_ACTION_TASKS,
                        session_id,
                    )
                )
                if (
                    session_id in BUSY_SESSIONS
                    or ACTIVE.get(session_id) is not None
                    or session_id in SERVER_MAINTENANCE_SESSIONS
                    or provider_starting
                    or native_action_active
                ):
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            "Wait for or stop the active provider work before "
                            "reloading this chat."
                        ),
                    )
                SERVER_MAINTENANCE_SESSIONS.add(session_id)
                maintenance_reserved = True

            cleared_interactions = await clear_stale_provider_interactions(
                session_id,
                backend,
            )
            provider_id = str(session_provider_id(session) or "").strip()
            was_loaded = False

            if backend == BACKEND_CLAUDE:
                manager = CLAUDE_SDK_MANAGER
                if manager is not None:
                    try:
                        was_loaded = claude_manager_owns_chat(
                            manager,
                            session_id,
                        )
                    except Exception as exc:
                        raise HTTPException(
                            status_code=409,
                            detail=(
                                "Claude provider state could not be inspected; "
                                "reload was not attempted."
                            ),
                        ) from exc
                    if was_loaded:
                        try:
                            active_children = max(
                                0,
                                int(
                                    build_claude_subagent_snapshot(
                                        session_id,
                                        limit=1,
                                    ).get("active_count")
                                    or 0
                                ),
                            )
                        except Exception as exc:
                            raise HTTPException(
                                status_code=409,
                                detail=(
                                    "Claude background-agent state could not be "
                                    "inspected; reload was not attempted."
                                ),
                            ) from exc
                        if active_children:
                            raise HTTPException(
                                status_code=409,
                                detail=(
                                    "Stop the Claude background agents before "
                                    "reloading this chat."
                                ),
                            )
                        evicted = await evict_claude_sdk_chat(
                            session_id,
                            force=False,
                            manager=manager,
                        )
                        try:
                            still_owned = claude_manager_owns_chat(
                                manager,
                                session_id,
                            )
                        except Exception as exc:
                            raise HTTPException(
                                status_code=409,
                                detail=(
                                    "Claude provider state could not be "
                                    "verified after reload."
                                ),
                            ) from exc
                        if not evicted or still_owned:
                            raise HTTPException(
                                status_code=409,
                                detail=(
                                    "Claude is still using this chat; wait for "
                                    "its provider lifecycle to become idle."
                                ),
                            )
                runtime = await claude_runtime_snapshot(session_id)
            else:
                manager = CODEX_APP_SERVER_MANAGER
                if codex_session_has_live_subagents(session_id):
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            "Stop the Codex subagents before reloading this chat."
                        ),
                    )
                if provider_id and manager is not None:
                    was_loaded = bool(manager.is_thread_loaded(provider_id))
                    if was_loaded:
                        try:
                            terminals = await manager.list_background_terminals(
                                provider_id
                            )
                        except CodexAppServerRequestError as exc:
                            if exc.code not in {-32600, -32601}:
                                raise HTTPException(
                                    status_code=409,
                                    detail=(
                                        "Codex background-terminal state could "
                                        "not be inspected; reload was not attempted."
                                    ),
                                ) from exc
                            terminals = []
                        except Exception as exc:
                            raise HTTPException(
                                status_code=409,
                                detail=(
                                    "Codex background-terminal state could not "
                                    "be inspected; reload was not attempted."
                                ),
                            ) from exc
                        if terminals:
                            raise HTTPException(
                                status_code=409,
                                detail=(
                                    "Stop the Codex background terminals before "
                                    "reloading this chat."
                                ),
                            )
                        evicted = await evict_codex_app_server_thread(
                            manager,
                            provider_id,
                            reinsert_on_failure=True,
                        )
                        if not evicted and manager.is_thread_loaded(provider_id):
                            raise HTTPException(
                                status_code=409,
                                detail=(
                                    "Codex is still using this thread; wait for "
                                    "its provider lifecycle to become idle."
                                ),
                            )
                runtime = await codex_runtime_snapshot(session_id)

            latest_session = STORE.sessions.get(session_id) or session
            return {
                "reloaded": True,
                "backend": backend,
                "provider_id": provider_id or None,
                "was_loaded": was_loaded,
                "action": "unloaded" if was_loaded else "already_unloaded",
                "cleared_stale_interactions": cleared_interactions,
                "session": public_session(latest_session),
                "runtime": runtime,
            }
        finally:
            if maintenance_reserved:
                async with ACTIVE_LOCK:
                    SERVER_MAINTENANCE_SESSIONS.discard(session_id)


@app.post("/api/sessions/{session_id}/provider/reload")
async def post_session_provider_reload(session_id: str) -> dict[str, Any]:
    return await reload_session_provider(session_id)


@app.get("/api/sessions/{session_id}/codex/runtime")
async def get_codex_runtime(session_id: str) -> dict[str, Any]:
    return await codex_runtime_snapshot(session_id)


@app.post("/api/sessions/{session_id}/codex/load")
async def load_codex_runtime(session_id: str) -> dict[str, Any]:
    """Resume a persisted Codex thread without creating provider state."""

    async with session_lifecycle_lock(session_id):
        ensure_session_not_deleting(session_id)
        session = STORE.sessions.get(session_id)
        if not session:
            raise HTTPException(status_code=404, detail="session not found")
        if str(session.get("backend") or DEFAULT_BACKEND) != BACKEND_CODEX:
            raise HTTPException(
                status_code=409,
                detail="Codex thread loading requires a Codex chat",
            )
        if CODEX_TRANSPORT == CODEX_TRANSPORT_EXEC:
            raise HTTPException(
                status_code=503,
                detail="Codex thread loading requires the app-server transport",
            )

        provider_id = str(session_provider_id(session) or "").strip()
        async with ACTIVE_LOCK:
            if (
                session_id in BUSY_SESSIONS
                or session_id in SERVER_MAINTENANCE_SESSIONS
            ):
                raise HTTPException(
                    status_code=409,
                    detail="wait for the active Codex turn to finish",
                )
            update_blocker = managed_server_update_blocker()
            if update_blocker:
                raise HTTPException(status_code=503, detail=update_blocker)

        # A new chat has no persisted provider thread to resume.  Returning the
        # normal snapshot keeps the endpoint idempotent and, importantly, does
        # not turn merely selecting a chat into thread/start.
        if not provider_id:
            return await codex_runtime_snapshot(session_id)

        manager: CodexAppServerManager | None = None
        maintenance_reserved = False
        loaded_thread_id = ""
        runtime: dict[str, Any] | None = None
        try:
            # Reserve only for the duration of thread/resume. This participates
            # in update admission without making the chat look like it has an
            # active user turn.
            async with ACTIVE_LOCK:
                if (
                    session_id in BUSY_SESSIONS
                    or session_id in SERVER_MAINTENANCE_SESSIONS
                ):
                    raise HTTPException(
                        status_code=409,
                        detail="wait for the active Codex turn to finish",
                    )
                update_blocker = managed_server_update_blocker()
                if update_blocker:
                    raise HTTPException(status_code=503, detail=update_blocker)
                SERVER_MAINTENANCE_SESSIONS.add(session_id)
                maintenance_reserved = True

            manager = await codex_app_server_manager()
            cwd = existing_cwd(str(session.get("cwd") or DEFAULT_CWD))
            loaded_thread_id, _instruction_hash = (
                await ensure_codex_app_server_thread(
                    manager,
                    session_id,
                    session,
                    cwd,
                )
            )
            # Snapshot while ensure's pin is still held. An LRU eviction cannot
            # turn a successful load into a stale ``thread_loaded`` response.
            runtime = await codex_runtime_snapshot(session_id)
        except HTTPException:
            raise
        except Exception as exc:
            raise codex_control_http_error(exc) from exc
        finally:
            if loaded_thread_id and manager is not None:
                with suppress(Exception):
                    await unpin_codex_app_server_thread(
                        manager,
                        loaded_thread_id,
                    )
            if maintenance_reserved:
                async with ACTIVE_LOCK:
                    SERVER_MAINTENANCE_SESSIONS.discard(session_id)

        assert runtime is not None
        return runtime


