@app.websocket("/api/sessions/{session_id}/terminal/ws")
async def session_terminal(
    session_id: str,
    ws: WebSocket,
    columns: int = 120,
    rows: int = 36,
    cwd: str | None = None,
) -> None:
    if not websocket_authorized(ws):
        await ws.accept()
        await ws.close(code=4401)
        return
    if session_id not in STORE.sessions:
        await ws.accept()
        await ws.close(code=4404)
        return
    if bool(STORE.sessions[session_id].get("archived")):
        await ws.accept()
        await ws.close(code=4409)
        return

    cols, lines = terminal_dimensions(columns, rows)
    await ws.accept()
    process: subprocess.Popen[bytes] | None = None
    master_fd: int | None = None
    try:
        process, master_fd, name = await asyncio.to_thread(
            spawn_terminal_client,
            session_id,
            cwd,
            cols,
            lines,
        )
        await ws.send_json({
            "type": "ready",
            "session_id": session_id,
            "name": name,
            "columns": cols,
            "rows": lines,
        })

        async def pump_output() -> None:
            assert master_fd is not None
            while True:
                try:
                    data = await read_terminal_output(master_fd)
                except OSError as exc:
                    if exc.errno in {errno.EIO, errno.EBADF}:
                        return
                    raise
                if not data:
                    return
                await ws.send_bytes(data)

        async def receive_input() -> None:
            assert master_fd is not None
            auto_scroll_mode = False
            try:
                while True:
                    message = await ws.receive()
                    if message["type"] == "websocket.disconnect":
                        return
                    data = message.get("bytes")
                    if data:
                        if auto_scroll_mode:
                            await asyncio.to_thread(exit_terminal_auto_scroll, session_id)
                            auto_scroll_mode = False
                        write_terminal_input(master_fd, data)
                        continue
                    text = message.get("text")
                    if not text:
                        continue
                    try:
                        control = json.loads(text)
                    except json.JSONDecodeError:
                        continue
                    if control.get("type") == "resize":
                        next_cols, next_rows = terminal_dimensions(control.get("columns"), control.get("rows"))
                        set_pty_dimensions(master_fd, next_cols, next_rows)
                        await asyncio.to_thread(resize_terminal_window, session_id, next_cols, next_rows)
                    elif control.get("type") == "scroll":
                        with suppress(TypeError, ValueError):
                            auto_scroll_mode = await asyncio.to_thread(
                                scroll_terminal_history,
                                session_id,
                                int(control.get("delta") or 0),
                                managed=auto_scroll_mode,
                            )
            finally:
                if auto_scroll_mode:
                    await asyncio.to_thread(exit_terminal_auto_scroll, session_id)

        output_task = asyncio.create_task(pump_output())
        input_task = asyncio.create_task(receive_input())
        done, pending = await asyncio.wait(
            {output_task, input_task},
            return_when=asyncio.FIRST_COMPLETED,
        )
        for task in pending:
            task.cancel()
        await asyncio.gather(*pending, return_exceptions=True)
        for task in done:
            with suppress(WebSocketDisconnect, RuntimeError, OSError):
                task.result()
    except WebSocketDisconnect:
        pass
    except Exception as exc:
        logger.warning("terminal websocket failed session=%s error=%s", session_id, exc)
        with suppress(RuntimeError):
            await ws.send_json({"type": "error", "message": str(exc)[:1000]})
    finally:
        if process is not None and master_fd is not None:
            await asyncio.to_thread(stop_terminal_client, process, master_fd)
        with suppress(RuntimeError):
            await ws.close()


@app.websocket("/api/sessions/{session_id}/events")
async def session_events(
    session_id: str,
    ws: WebSocket,
    after: int = 0,
    visible: bool | None = None,
) -> None:
    if not websocket_authorized(ws):
        await ws.close(code=4401)
        return
    if session_id not in STORE.sessions:
        await ws.close(code=4404)
        return
    await ws.accept()
    try:
        cursor = max(0, int(after or 0))
        if visible is None:
            # Preserve the bounded legacy handshake for clients that have not
            # opted into full filtered catch-up (including current iOS builds).
            async with event_delivery_lock(session_id):
                legacy_events = await asyncio.to_thread(
                    read_events,
                    session_id,
                    after=cursor,
                )
                for event in legacy_events:
                    await asyncio.wait_for(
                        ws.send_json(event),
                        timeout=WEBSOCKET_SEND_TIMEOUT_SECONDS,
                    )
                await HUB.register_accepted(session_id, ws)
        else:
            boundary = last_event_seq_from_file(events_path(session_id))
            cursor = await send_event_catchup(
                session_id,
                ws,
                after=cursor,
                through=boundary,
                visible=visible,
            )
            # The delivery lock closes the replay/register race for this chat:
            # racing appends finish before the gap boundary, while later
            # appends cannot write until the socket has been registered.
            async with event_delivery_lock(session_id):
                gap_boundary = last_event_seq_from_file(events_path(session_id))
                await send_event_catchup(
                    session_id,
                    ws,
                    after=cursor,
                    through=gap_boundary,
                    visible=visible,
                )
                await HUB.register_accepted(session_id, ws)
        while True:
            await ws.receive_text()
    except WebSocketDisconnect:
        pass
    finally:
        await HUB.unsubscribe(session_id, ws)


