@app.api_route("/api/sessions/{session_id}/workspace/preview", methods=["GET", "HEAD"])
async def get_session_workspace_preview(
    request: Request,
    session_id: str,
    path: str = Query(min_length=1, max_length=MAX_WORKSPACE_PATH_CHARS),
) -> Response:
    preview = await asyncio.to_thread(open_workspace_preview_sync, session_id, path)
    file_fd = int(preview["file_fd"])
    try:
        size = int(preview["size"])
        byte_range = parse_workspace_preview_range(request.headers.get("range"), size)
        start, end = byte_range if byte_range is not None else (0, max(0, size - 1))
        length = end - start + 1 if size else 0
        status_code = 206 if byte_range is not None else 200
        revision = str(preview["revision"])
        headers = {
            "Accept-Ranges": "bytes",
            "Cache-Control": "no-store",
            "Content-Length": str(length),
            "Content-Disposition": "inline",
            "ETag": f'"{revision}"',
            "X-AgentsDock-Revision": revision,
            "X-Content-Type-Options": "nosniff",
        }
        if byte_range is not None:
            headers["Content-Range"] = f"bytes {start}-{end}/{size}"
        if request.method.upper() == "HEAD":
            os.close(file_fd)
            file_fd = -1
            return Response(
                content=b"",
                status_code=status_code,
                headers=headers,
                media_type=str(preview["media_type"]),
            )
        body = stream_workspace_preview(file_fd, start, length)
        file_fd = -1
        return StreamingResponse(
            body,
            status_code=status_code,
            headers=headers,
            media_type=str(preview["media_type"]),
        )
    finally:
        if file_fd >= 0:
            os.close(file_fd)


@app.api_route("/api/sessions/{session_id}/workspace/download", methods=["GET", "HEAD"])
async def get_session_workspace_download(
    request: Request,
    session_id: str,
    path: str = Query(min_length=1, max_length=MAX_WORKSPACE_PATH_CHARS),
) -> Response:
    download = await asyncio.to_thread(open_workspace_download_sync, session_id, path)
    file_fd = int(download["file_fd"])
    try:
        size = int(download["size"])
        revision = str(download["revision"])
        filename = quote(str(download["name"]), safe="")
        headers = {
            "Cache-Control": "no-store",
            "Content-Length": str(size),
            "Content-Disposition": f"attachment; filename*=UTF-8''{filename}",
            "ETag": f'"{revision}"',
            "X-AgentsDock-Revision": revision,
            "X-Content-Type-Options": "nosniff",
        }
        if request.method.upper() == "HEAD":
            os.close(file_fd)
            file_fd = -1
            return Response(
                content=b"",
                headers=headers,
                media_type="application/octet-stream",
            )
        body = stream_workspace_preview(file_fd, 0, size)
        file_fd = -1
        return StreamingResponse(
            body,
            headers=headers,
            media_type="application/octet-stream",
        )
    finally:
        if file_fd >= 0:
            os.close(file_fd)


