async def active_artifact_publication_run(
    session_id: str,
) -> tuple[str, dict[str, Any]]:
    async with ACTIVE_LOCK:
        current = CURRENT_TURNS.get(session_id)
        active = ACTIVE.get(session_id)
        run_id = str((current or {}).get("run_id") or "").strip()
        if (
            session_id not in BUSY_SESSIONS
            or not isinstance(current, dict)
            or not isinstance(active, dict)
            or not run_id
            or str(active.get("run_id") or "").strip() != run_id
            or active.get("codex_native_operation") is True
            or active.get("stop_requested") is True
            or run_id in STOPPED_RUNS
        ):
            raise HTTPException(
                status_code=409,
                detail="no active agent turn can receive artifacts for this chat",
            )
        return run_id, run_event_metadata(run_id)


def publication_response(
    session_id: str,
    publication_id: str,
    events: list[dict[str, Any]],
) -> dict[str, Any]:
    return {
        "ok": True,
        "chat_id": session_id,
        "publication_id": publication_id,
        "run_id": events[0].get("run_id") if events else None,
        "receipts": [artifact_event_receipt(event) for event in events],
    }


@app.post("/api/agent/sessions/{session_id}/artifacts")
async def publish_agent_artifacts(
    request: Request,
    session_id: str,
    req: PublishArtifactsRequest,
) -> dict[str, Any]:
    await authorize_provider_action(request, action="publish", session_id=session_id)
    if session_id not in STORE.sessions:
        raise HTTPException(status_code=404, detail="session not found")
    ensure_session_not_deleting(session_id)

    try:
        publication_id, entries, digest = await asyncio.to_thread(
            normalized_artifact_request,
            req.publication_id,
            req.files,
        )
    except ArtifactPublicationError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc

    # O(1) idempotency lookup precedes the active-run requirement. A retry
    # after a lost response must retrieve its original durable receipts even if
    # the turn has since finished or another turn has started.
    try:
        existing = await asyncio.to_thread(
            load_publication_events,
            session_id,
            publication_id,
        )
        receipt_sidecar_exists = bool(existing)
        if not existing and request.headers.get("x-agentsdock-publication-retry") == "1":
            existing = await asyncio.to_thread(
                recover_publication_events_from_tail,
                session_id,
                publication_id,
            )
        if existing:
            original_run_id = str(existing[0].get("run_id") or "")
            verified = await asyncio.to_thread(
                verified_publication_events,
                existing,
                run_id=original_run_id,
                publication_id=publication_id,
                publication_digest=digest,
                expected_count=len(entries),
            )
            if not receipt_sidecar_exists:
                try:
                    await asyncio.to_thread(
                        store_publication_events,
                        session_id,
                        publication_id,
                        verified,
                    )
                except BaseException as exc:
                    logger.warning(
                        "recovered publication sidecar repair failed session=%s publication=%s: %s",
                        session_id,
                        publication_id,
                        concise_error_message(exc),
                    )
            return publication_response(session_id, publication_id, verified)
    except ArtifactPublicationError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc

    run_id, metadata = await active_artifact_publication_run(session_id)
    try:
        entries = await asyncio.to_thread(normalize_artifact_entries, entries)
    except ArtifactPublicationError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    publication_task = asyncio.create_task(publish_artifact_entries(
        session_id,
        run_id,
        entries,
        publication_id=publication_id,
        publication_digest=digest,
        metadata=metadata,
    ))
    try:
        events = await asyncio.shield(publication_task)
    except BaseException as exc:
        if isinstance(exc, (KeyboardInterrupt, SystemExit)):
            raise
        try:
            events = await join_task_despite_caller_cancellation(publication_task)
        except ArtifactPublicationError as publication_exc:
            raise HTTPException(status_code=409, detail=str(publication_exc)) from publication_exc
        except BaseException as publication_exc:
            if isinstance(publication_exc, (KeyboardInterrupt, SystemExit)):
                raise
            logger.exception(
                "agent artifact publication failed session=%s run=%s publication=%s",
                session_id,
                run_id,
                publication_id,
            )
            raise HTTPException(
                status_code=500,
                detail=f"artifact publication failed: {concise_error_message(publication_exc)}",
            ) from publication_exc
    return publication_response(session_id, publication_id, events)


@app.post("/api/sessions/{session_id}/files")
async def upload_file(session_id: str, file: UploadFile = File(...)) -> dict[str, Any]:
    if session_id not in STORE.sessions:
        raise HTTPException(status_code=404, detail="session not found")
    file_id = f"file_{uuid.uuid4().hex[:16]}"
    dest_dir = FILES_ROOT / file_id
    dest_dir.mkdir(parents=True, exist_ok=True)
    dest = dest_dir / safe_name(file.filename or "upload")
    size = 0
    with dest.open("wb") as out:
        while True:
            chunk = await file.read(1024 * 1024)
            if not chunk:
                break
            size += len(chunk)
            if size > MAX_UPLOAD_BYTES:
                raise HTTPException(status_code=413, detail="upload too large")
            out.write(chunk)
    meta = {
        "id": file_id,
        "session_id": session_id,
        "kind": "upload",
        "filename": dest.name,
        "path": str(dest),
        "size": size,
        "content_type": effective_content_type(dest.name, file.content_type),
        "created_at": now_iso(),
    }
    (dest_dir / "meta.json").write_text(json.dumps(meta, indent=2))
    await append_event(session_id, "file_uploaded", {"file": meta})
    return {"file": meta}


def load_file_meta(file_id: str) -> dict[str, Any]:
    clean_file_id = normalized_file_id(file_id)
    if not clean_file_id:
        raise HTTPException(status_code=404, detail="file not found")
    meta_path = FILES_ROOT / clean_file_id / "meta.json"
    if meta_path.exists():
        return json.loads(meta_path.read_text())
    file_dir = FILES_ROOT / clean_file_id
    if not file_dir.is_dir():
        raise HTTPException(status_code=404, detail="file not found")
    files = [p for p in file_dir.iterdir() if p.is_file() and p.name != "meta.json"]
    if len(files) != 1:
        raise HTTPException(status_code=404, detail="file not found")
    path = files[0]
    meta = {
        "id": clean_file_id,
        "kind": "artifact",
        "filename": path.name,
        "path": str(path),
        "size": path.stat().st_size,
        "content_type": guess_content_type(path.name),
        "created_at": now_iso(),
    }
    meta_path.write_text(json.dumps(meta, indent=2))
    return meta


def iter_session_events(session_id: str):
    path = events_path(session_id)
    if not path.exists():
        return
    with path.open("r", encoding="utf-8", errors="ignore") as stream:
        for line in stream:
            if not line.strip():
                continue
            try:
                event = json.loads(line)
            except Exception:
                continue
            if event_files_belong_to_session(event, session_id):
                yield event


def file_event_record(event: dict[str, Any], file_id: str, session_id: str | None = None) -> dict[str, Any] | None:
    for key in ("file", "artifact"):
        rec = event.get(key)
        if isinstance(rec, dict) and str(rec.get("id") or "") == file_id:
            if session_id is not None and not file_record_belongs_to_session(rec, session_id):
                continue
            out = dict(rec)
            out["event_id"] = event.get("id")
            out["event_seq"] = event.get("seq")
            out["event_type"] = event.get("type")
            return out
    return None


def list_session_file_records(session_id: str) -> list[dict[str, Any]]:
    records: dict[str, dict[str, Any]] = {}
    for meta_path in FILES_ROOT.glob("*/meta.json"):
        try:
            rec = json.loads(meta_path.read_text())
        except Exception:
            continue
        if rec.get("session_id") == session_id and rec.get("id"):
            records[str(rec["id"])] = rec

    for event in iter_session_events(session_id):
        for key in ("file", "artifact"):
            rec = event.get(key)
            if (
                isinstance(rec, dict)
                and rec.get("id")
                and file_record_belongs_to_session(rec, session_id)
            ):
                if (
                    not str(rec.get("session_id") or "").strip()
                    and not event_establishes_session_file_origin(event, session_id)
                ):
                    continue
                meta = read_file_meta_record(str(rec.get("id") or ""))
                meta_owner = str((meta or {}).get("session_id") or "").strip()
                if meta_owner and meta_owner != session_id:
                    continue
                out = dict(rec)
                out["event_id"] = event.get("id")
                out["event_seq"] = event.get("seq")
                out["event_type"] = event.get("type")
                records[str(rec["id"])] = out

    normalized = []
    for rec in records.values():
        current = dict(rec)
        filename = str(current.get("filename") or Path(str(current.get("path") or "")).name)
        current["content_type"] = effective_content_type(filename, str(current.get("content_type") or ""))
        normalized.append(current)

    return sorted(
        normalized,
        key=lambda rec: (str(rec.get("created_at") or ""), str(rec.get("filename") or "")),
        reverse=True,
    )


@app.get("/api/sessions/{session_id}/files")
async def list_session_files(
    session_id: str,
    limit: int | None = Query(default=None, ge=1, le=200),
    offset: int = Query(default=0, ge=0),
    content_prefix: str | None = Query(default=None),
) -> dict[str, Any]:
    if session_id not in STORE.sessions:
        raise HTTPException(status_code=404, detail="session not found")
    records = list_session_file_records(session_id)
    if content_prefix:
        prefix = content_prefix.strip().lower()
        records = [
            rec for rec in records
            if str(rec.get("content_type") or "").lower().startswith(prefix)
        ]
    total = len(records)
    if limit is None:
        return {
            "files": records,
            "total": total,
            "offset": 0,
            "limit": total,
            "has_more": False,
        }
    page = records[offset:offset + limit]
    return {
        "files": page,
        "total": total,
        "offset": offset,
        "limit": limit,
        "has_more": offset + len(page) < total,
    }


@app.get("/api/sessions/{session_id}/files/{file_id}/event")
async def get_session_file_event(session_id: str, file_id: str) -> dict[str, Any]:
    if session_id not in STORE.sessions:
        raise HTTPException(status_code=404, detail="session not found")
    clean_file_id = validate_session_file_ids(session_id, [file_id])[0]
    for event in iter_session_events(session_id):
        if file_event_record(event, clean_file_id, session_id):
            return {"event": event}
    raise HTTPException(status_code=404, detail="file event not found")


@app.get("/api/sessions/{session_id}/links/file")
@app.head("/api/sessions/{session_id}/links/file")
async def get_session_linked_file(session_id: str, target: str) -> FileResponse:
    if session_id not in STORE.sessions:
        raise HTTPException(status_code=404, detail="session not found")
    meta = session_file_for_link(session_id, target)
    return FileResponse(
        meta["path"],
        media_type=file_response_media_type(meta),
        filename=meta.get("filename"),
        content_disposition_type="inline",
    )


@app.get("/api/sessions/{session_id}/files/{file_id}")
@app.head("/api/sessions/{session_id}/files/{file_id}")
async def get_session_file(session_id: str, file_id: str) -> FileResponse:
    if session_id not in STORE.sessions:
        raise HTTPException(status_code=404, detail="session not found")
    meta = require_session_file_meta(session_id, file_id)
    return FileResponse(
        meta["path"],
        media_type=file_response_media_type(meta),
        filename=meta.get("filename"),
        content_disposition_type="inline",
    )


@app.get("/api/files/{file_id}")
@app.head("/api/files/{file_id}")
async def get_file(
    file_id: str,
    session_id: str | None = Query(default=None, min_length=1),
) -> FileResponse:
    """Compatibility alias for clients predating chat-scoped download URLs.

    New clients use ``/api/sessions/{session_id}/files/{file_id}``. Keep the
    historical route during the transition so a server-first rollout does not
    break already-installed desktop and mobile clients.
    """
    if session_id is not None:
        if session_id not in STORE.sessions:
            raise HTTPException(status_code=404, detail="session not found")
        meta = require_session_file_meta(session_id, file_id)
    else:
        logger.warning("legacy unscoped file download file_id=%s", normalized_file_id(file_id))
        meta = load_file_meta(file_id)
    return FileResponse(
        meta["path"],
        media_type=file_response_media_type(meta),
        filename=meta.get("filename"),
        content_disposition_type="inline",
    )


def main() -> int:
    logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(name)s: %(message)s")
    parser = argparse.ArgumentParser(description="AgentsServer")
    parser.add_argument("cmd", nargs="?", default="serve", choices=["serve"])
    parser.add_argument("--bind", default=agentsdock_setting("AGENT_BIND", "0.0.0.0"))
    parser.add_argument("--port", type=int, default=int(agentsdock_setting("AGENT_PORT", "7850")))
    args = parser.parse_args()
    uvicorn.run("agent_server:app", host=args.bind, port=args.port, app_dir=str(Path(__file__).parent), log_level="info")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
